class Iface_InterfaceManager
  include Cpp::ICopy
  attr_accessor :data_, :infile_, :outfile_, :old_time_, :new_time_, :n_iface_polluts_, :n_values_per_node_, :iface_flow_units_, :iface_step_, :iface_frac_, :pollut_map_

  def initialize
    @data_ = nil
    @infile_ = nil
    @outfile_ = nil
    @old_time_ = 0.0
    @new_time_ = 0.0
    @n_iface_polluts_ = 0
    @n_values_per_node_ = 0
    @iface_flow_units_ = 0
    @iface_step_ = 0
    @iface_frac_ = 0.0
    @pollut_map_ = nil
  end

  def init(p)
    self.closeFiles()
    @data_.count = 0
    @infile_ = nil
    @outfile_ = nil
    @old_time_ = 0.0
    @new_time_ = 0.0
    @n_iface_polluts_ = 0
    @n_values_per_node_ = 1
    @iface_frac_ = 0.0
    @pollut_map_.clear()
  end

  def openFiles(infile_path, outfile_path)
    if (!(infile_path.n == 0)) && (!(outfile_path.n == 0))
      if infile_path.Equals_Str(outfile_path)
        return -1
      end
    end
    if !(outfile_path.n == 0)
      @outfile_ = F_io_fopen_utf8(outfile_path, R_Lit("wt"))
      if !(!@outfile_.nil?)
        return -2
      end
    end
    if !(infile_path.n == 0)
