  def stepRouting(dt_routing)
    @quality_.beginFvWindow()
    @last_step_steady_ = false
    routing_secs = (@ctx_.elapsed_ms + 1.0) / 1000.0
    routing_date = F_datetime_addSeconds(@ctx_.options.start_date, routing_secs)
    @between_events_ = self.isBetweenEvents(routing_date)
    if @between_events_
      Algo_fill_IterT_IterT_T__D(@ctx_.nodes.lat_flow.begin(), @ctx_.nodes.lat_flow.end(), 0.0)
      if !@ctx_.options.ignore_quality
        Algo_fill_IterT_IterT_T__D(@ctx_.nodes.conc.begin(), @ctx_.nodes.conc.end(), 0.0)
        Algo_fill_IterT_IterT_T__D(@ctx_.links.conc.begin(), @ctx_.links.conc.end(), 0.0)
      end
      if (@next_event_ < ((@ctx_.events.n + 0x80000000 & 0xFFFFFFFF) - 0x80000000)) && (routing_date > @ctx_.events.a[@next_event_ < 0 ? @next_event_ + 0x10000000000000000 : @next_event_].end_)
        @next_event_ += 1
      end
      return
    end
    @hydstruct_.updatePumpTargetSettings(@ctx_)
    rule_time_reached = (@ctx_.options.rule_step <= 0.0) || ((@ctx_.elapsed_ms - @new_rule_time_ms_).abs < 1.0)
    @controls_.evaluate(@ctx_, routing_date, dt_routing, rule_time_reached)
    j = 0
    while j < @ctx_.n_links()
      uj = j < 0 ? j + 0x10000000000000000 : j
      target = @ctx_.links.target_setting.a[uj]
      current = @ctx_.links.setting.a[uj]
      if target != current
        if (target * current) == 0.0
          @ctx_.links.time_last_set.a[uj] = routing_date
        end
        orr = @ctx_.link_subtypes.orifice_row(j)
        orate_sec = ((orr >= 0) ? @ctx_.link_subtypes.orifices.orate.a[orr < 0 ? orr + 0x10000000000000000 : orr] : 0.0) * 3600.0
        if (orate_sec > 0.0) && (dt_routing > 0.0)
          step = orate_sec != 0.0 ? dt_routing / orate_sec : fdiv0(dt_routing, orate_sec)
          delta_val = (target - current).abs
          if (step + 0.001) >= delta_val
            @ctx_.links.setting.a[uj] = target
          elsif target > current
            @ctx_.links.setting.a[uj] = current + step
          else
            @ctx_.links.setting.a[uj] = current - step
          end
        else
          @ctx_.links.setting.a[uj] = target
        end
      end
      j += 1
    end
    @ctx_.nodes.clearInflowSources()
    @inflow_.computeAll(@ctx_, routing_date, dt_routing)
    if !@ctx_.options.ignore_quality
      F_msxsurf_deliver(@ctx_, dt_routing)
    end
    if !@ctx_.options.ignore_quality
      F_transport_drainMsxCouplingQueue(@ctx_, dt_routing)
    end
    if !@ctx_.options.ignore_rdii
      if @rdii_iface_file_.isOpen() && (!@rdii_iface_file_.isWriting())
        @rdii_iface_file_.applyFlows(@ctx_, routing_date)
      else
        @rdii_.applyRdiiInflows(@ctx_, routing_secs)
      end
    end
    @iface_.readInflows(@ctx_, routing_date)
    self.assembleLateralInflows(dt_routing)
    action_count = @controls_.lastActionCount()
