            ctx.nodes.depth.a[a < 0 ? a + 0x10000000000000000 : a] = F_lidnode_portDepth(ctx, a, F_lidnode_portOffset(ctx, j_2, a))
            ctx.nodes.depth.a[b < 0 ? b + 0x10000000000000000 : b] = F_lidnode_portDepth(ctx, b, F_lidnode_portOffset(ctx, j_2, b))
            ctx.nodes.head.a[a < 0 ? a + 0x10000000000000000 : a] = ctx.nodes.invert_elev.a[a < 0 ? a + 0x10000000000000000 : a] + ctx.nodes.depth.a[a < 0 ? a + 0x10000000000000000 : a]
            ctx.nodes.head.a[b < 0 ? b + 0x10000000000000000 : b] = ctx.nodes.invert_elev.a[b < 0 ? b + 0x10000000000000000 : b] + ctx.nodes.depth.a[b < 0 ? b + 0x10000000000000000 : b]
            ctx.nodes.old_volume.a[a < 0 ? a + 0x10000000000000000 : a] += F_lidnode_heldVolume(ctx, a)
            ctx.nodes.old_volume.a[b < 0 ? b + 0x10000000000000000 : b] += F_lidnode_heldVolume(ctx, b)
            @hydstruct_.computeNonConduitFlowOne(ctx, dt, surf_buf, j_2)
            ctx.nodes.depth.a[a < 0 ? a + 0x10000000000000000 : a] = da
            ctx.nodes.depth.a[b < 0 ? b + 0x10000000000000000 : b] = db
            ctx.nodes.head.a[a < 0 ? a + 0x10000000000000000 : a] = ha
            ctx.nodes.head.a[b < 0 ? b + 0x10000000000000000 : b] = hb
