            end
          end
          links.flow.a[uj_2] = q_new
        else
          @hydstruct_.scatterHeldSurfArea(ctx, surf_buf, j_2)
        end
        before_surface = links.flow.a[uj_2]
        links.flow.a[uj_2] = F_boundSurfaceOutfallFlow(ctx, j_2, before_surface)
        if links.flow.a[uj_2] != before_surface
