    end
    non_conduit_fn = _lam5
    @exfil_.computeAll(@ctx_, dt_routing)
    iters = 0
    _pt_1d = perf_ScopedTimer_New_rd(SR_F_perf_sec_1d_step.new)
    iters = @checkpoint_enabled_ ? @router_.stepImpl(@ctx_, dt_routing, @ctx_.climate_state.evap_rate, non_conduit_fn, true) : @router_.step__rSimulationContext_d_d_fn(@ctx_, dt_routing, @ctx_.climate_state.evap_rate, non_conduit_fn)
