        __b1 = [bits.v]
        Mv_Back__OQ(Mem_memcpy_PtrT_PtrU_ul__LD(NewPtrL_TA_l(__b1, 0), NewPtrD_TA_l(@ctx_.links.flow.a, ((tj < 0 ? tj + 0x10000000000000000 : tj) + 0x8000000000000000 & 0xFFFFFFFFFFFFFFFF) - 0x8000000000000000), 8), bits, __b1)
        q_hash = ((q_hash ^ bits.v) * 1099511628211) & 0xFFFFFFFFFFFFFFFF
        tj += 1
      end
      tj_2 = 0
      while tj_2 < @ctx_.n_nodes()
        y_sum += @ctx_.nodes.depth.a[tj_2 < 0 ? tj_2 + 0x10000000000000000 : tj_2]
        __b2 = [bits.v]
        Mv_Back__OQ(Mem_memcpy_PtrT_PtrU_ul__LD(NewPtrL_TA_l(__b2, 0), NewPtrD_TA_l(@ctx_.nodes.depth.a, ((tj_2 < 0 ? tj_2 + 0x10000000000000000 : tj_2) + 0x8000000000000000 & 0xFFFFFFFFFFFFFFFF) - 0x8000000000000000), 8), bits, __b2)
        y_hash = ((y_hash ^ bits.v) * 1099511628211) & 0xFFFFFFFFFFFFFFFF
        tj_2 += 1
      end
      tj_3 = 0
      while tj_3 < @ctx_.n_nodes()
        l_sum += @ctx_.nodes.lat_flow.a[tj_3 < 0 ? tj_3 + 0x10000000000000000 : tj_3]
        tj_3 += 1
      end
      tj_4 = 0
      while tj_4 < @ctx_.n_subcatches()
        ro_sum += @ctx_.subcatches.runoff.a[tj_4 < 0 ? tj_4 + 0x10000000000000000 : tj_4]
        tj_4 += 1
      end
      R_fprintf($SWMMEngine_S_trace_file_50, R_Lit("%ld,%.6f,%.6f,%d,%a,%a,%a,%a,%016llx,%016llx\n"), I64(($SWMMEngine_S_trace_sn_52 = $SWMMEngine_S_trace_sn_52 + 1)), @ctx_.elapsed_ms + (1000.0 * dt_routing), 1000.0 * dt_routing, iters, q_sum, y_sum, l_sum, ro_sum, U64(q_hash), U64(y_hash))
      $F_g_trace_rstep_sn = $SWMMEngine_S_trace_sn_52
      if !$SWMMEngine_S_dump_init_54
