            R_fprintf(df, R_Lit("N,%d,%a,%a,%a,%a,%a\n"), tj_6, @ctx_.nodes.depth.a[utj_2], @ctx_.nodes.inflow.a[utj_2], @ctx_.nodes.outflow.a[utj_2], @ctx_.nodes.lat_flow.a[utj_2], @ctx_.nodes.old_lat_flow.a[utj_2])
            tj_6 += 1
