      elsif @ctx_.options.quality_solver == 2
        @quality_.assembleExternalLoads(@ctx_, dt_routing)
        @lard_.step__rSimulationContext_d(@ctx_, dt_routing)
      else
        @quality_.execute(@ctx_, dt_routing)
      end
    end
  end

  def updateStatistics(dt_routing)
    np = @ctx_.n_pollutants()
    stat_date = F_datetime_addSeconds(@ctx_.options.start_date, ((@ctx_.elapsed_ms + (1000.0 * dt_routing)) + 1.0) / 1000.0)
    if stat_date < @ctx_.options.report_start
      return
    end
    @ctx_.routing_stats.report_steps += 1
    @ctx_.routing_stats.report_time += dt_routing
    sys_outfall_flow = 0.0
    j = 0
    while j < @ctx_.n_nodes()
      uj = j < 0 ? j + 0x10000000000000000 : j
      cur_depth = @ctx_.nodes.depth.a[uj]
      @ctx_.nodes.stat_sum_depth.a[uj] += cur_depth
      if @ctx_.nodes.type.a[uj] == 3
        volume = @ctx_.nodes.volume.a[uj]
        @ctx_.nodes.stat_sum_volume.a[uj] += volume
        capped = (_m1 = @ctx_.nodes.full_volume.a[uj]; _m1 < volume ? _m1 : volume)
        if capped > @ctx_.nodes.stat_storage_max_volume.a[uj]
          @ctx_.nodes.stat_storage_max_volume.a[uj] = capped
          @ctx_.nodes.stat_storage_max_volume_date.a[uj] = stat_date
        end
      end
      if cur_depth > @ctx_.nodes.stat_max_depth.a[uj]
        @ctx_.nodes.stat_max_depth.a[uj] = cur_depth
        @ctx_.nodes.stat_max_depth_date.a[uj] = stat_date
      end
      if @ctx_.nodes.overflow.a[uj] > @ctx_.nodes.stat_max_overflow.a[uj]
        @ctx_.nodes.stat_max_overflow.a[uj] = @ctx_.nodes.overflow.a[uj]
        @ctx_.nodes.stat_max_overflow_date.a[uj] = stat_date
      end
      if @ctx_.nodes.type.a[uj] != 1
        if (@ctx_.nodes.volume.a[uj] > @ctx_.nodes.full_volume.a[uj]) || (@ctx_.nodes.overflow.a[uj] > 0.0)
          @ctx_.nodes.stat_time_flooded.a[uj] += dt_routing
          @ctx_.nodes.stat_vol_flooded.a[uj] += @ctx_.nodes.overflow.a[uj] * dt_routing
        end
        if ((@ctx_.options.routing_model == 2) && ((@ctx_.nodes.type.a[uj] != 3) || (@ctx_.nodes.sur_depth.a[uj] > 0.0))) && (((cur_depth + @ctx_.nodes.invert_elev.a[uj]) + $F_constants_FUDGE) >= @ctx_.nodes.crown_elev.a[uj])
          @ctx_.nodes.stat_time_surcharged.a[uj] += dt_routing
        end
      end
      lat = @ctx_.nodes.lat_flow.a[uj]
      total_inflow = @ctx_.nodes.inflow.a[uj]
      if lat.abs > @ctx_.nodes.stat_max_lat_inflow.a[uj].abs
        @ctx_.nodes.stat_max_lat_inflow.a[uj] = lat
      end
      if total_inflow > @ctx_.nodes.stat_max_total_inflow.a[uj]
        @ctx_.nodes.stat_max_total_inflow.a[uj] = total_inflow
        @ctx_.nodes.stat_max_inflow_date.a[uj] = stat_date
      end
      lateral_pair = @ctx_.nodes.old_lat_flow.a[uj] + lat
      @ctx_.nodes.stat_lat_inflow_vol.a[uj] += (lateral_pair * 0.5) * dt_routing
      if (@ctx_.nodes.type.a[uj] == 3) && (@ctx_.nodes.outflow.a[uj] > @ctx_.nodes.stat_storage_max_outflow.a[uj])
        @ctx_.nodes.stat_storage_max_outflow.a[uj] = @ctx_.nodes.outflow.a[uj]
      end
      if @ctx_.nodes.type.a[uj] == 1
        qi = @ctx_.nodes.inflow.a[uj]
        sys_outfall_flow += qi
        if qi >= 0.001
          @ctx_.nodes.stat_outfall_avg_flow.a[uj] += qi
          if qi > @ctx_.nodes.stat_outfall_max_flow.a[uj]
            @ctx_.nodes.stat_outfall_max_flow.a[uj] = qi
          end
          @ctx_.nodes.stat_outfall_periods.a[uj] += 1
        end
        if np > 0
          base = (uj * (np < 0 ? np + 0x10000000000000000 : np)) & 0xFFFFFFFFFFFFFFFF
          p = 0
          p = 0
          while p < np
            idx = (base + p) & 0xFFFFFFFFFFFFFFFF
            if (idx < @ctx_.nodes.stat_total_load.n) && (idx < @ctx_.nodes.conc.n)
              @ctx_.nodes.stat_total_load.a[idx] += (qi * @ctx_.nodes.conc.a[idx]) * dt_routing
            end
            p += 1
          end
        end
      end
      j += 1
    end
    @ctx_.routing_stats.max_outfall_flow = @ctx_.routing_stats.max_outfall_flow < sys_outfall_flow ? sys_outfall_flow : @ctx_.routing_stats.max_outfall_flow
    self.ensureXspCache()
    step_slot_vol = 0.0
    step_stored_vol = 0.0
    j_2 = 0
    while j_2 < @ctx_.n_links()
      uj_2 = j_2 < 0 ? j_2 + 0x10000000000000000 : j_2
      q = @ctx_.links.flow.a[uj_2].abs
      if q > @ctx_.links.stat_max_flow.a[uj_2]
        @ctx_.links.stat_max_flow.a[uj_2] = q
        @ctx_.links.stat_max_flow_date.a[uj_2] = stat_date
      end
      @ctx_.links.stat_vol_flow.a[uj_2] += q * dt_routing
      vel = 0.0
      if @ctx_.links.type.a[uj_2] == 0
        cr = @ctx_.link_subtypes.conduit_row(j_2)
        nb = (cr >= 0) ? @ctx_.link_subtypes.conduits.barrels.a[cr < 0 ? cr + 0x10000000000000000 : cr] : 1
        vel = F_link_getVelocity(@xsp_cache_.a[uj_2], q, @ctx_.links.depth.a[uj_2], nb)
      end
      if vel > @ctx_.links.stat_max_veloc.a[uj_2]
        @ctx_.links.stat_max_veloc.a[uj_2] = vel
      end
      y_full = @ctx_.links.xsect_y_full.a[uj_2]
      d = @ctx_.links.depth.a[uj_2]
      filling = (y_full > 0.0) ? (y_full != 0.0 ? d / y_full : fdiv0(d, y_full)) : 0.0
      if filling > @ctx_.links.stat_max_filling.a[uj_2]
        @ctx_.links.stat_max_filling.a[uj_2] = filling
      end
      v = @ctx_.links.volume.a[uj_2]
      sv = @ctx_.links.slot_volume.a[uj_2]
      @ctx_.links.stat_vol_dt.a[uj_2] += v * dt_routing
      step_stored_vol += v
      if sv > 0.0
        @ctx_.links.stat_slot_vol_dt.a[uj_2] += sv * dt_routing
        step_slot_vol += sv
        share = (v > 0.0) ? (v != 0.0 ? sv / v : fdiv0(sv, v)) : 0.0
        if share > @ctx_.links.stat_peak_slot_share.a[uj_2]
          @ctx_.links.stat_peak_slot_share.a[uj_2] = share
        end
        if share > 0.01
          @ctx_.links.stat_time_slot_above.a[uj_2] += dt_routing
        end
      end
      if (@ctx_.links.type.a[uj_2] == 0) && (@ctx_.links.xsect_shape.a[uj_2] != 25)
        n1 = @ctx_.links.node1.a[uj_2]
        n2 = @ctx_.links.node2.a[uj_2]
        cr_2 = @ctx_.link_subtypes.conduit_row(j_2)
        _CD = @ctx_.link_subtypes.conduits
        fc = @ctx_.links.flow_class.a[uj_2]
        if (fc >= 0) && (fc < $LinkData_N_FLOW_CLASSES)
          fc_idx = ((uj_2 * ($LinkData_N_FLOW_CLASSES < 0 ? $LinkData_N_FLOW_CLASSES + 0x10000000000000000 : $LinkData_N_FLOW_CLASSES)) + (fc < 0 ? fc + 0x10000000000000000 : fc)) & 0xFFFFFFFFFFFFFFFF
          if fc_idx < @ctx_.links.stat_flow_class.n
            @ctx_.links.stat_flow_class.a[fc_idx] += dt_routing
          end
        end
        if cr_2 >= 0
          ucr = cr_2 < 0 ? cr_2 + 0x10000000000000000 : cr_2
          if q >= (_CD.q_full.a[ucr] * _CD.barrels.a[ucr])
            @ctx_.links.stat_time_full_both.a[uj_2] += dt_routing
          end
        end
        fs = (cr_2 >= 0) ? _CD.full_state.a[cr_2 < 0 ? cr_2 + 0x10000000000000000 : cr_2] : 0
        up_full = (fs & 1) != 0
        dn_full = (fs & 2) != 0
        if up_full && dn_full
          @ctx_.links.stat_time_surcharged.a[uj_2] += dt_routing
          @ctx_.links.stat_time_full_upstream.a[uj_2] += dt_routing
          @ctx_.links.stat_time_full_dnstream.a[uj_2] += dt_routing
        elsif up_full
          @ctx_.links.stat_time_full_upstream.a[uj_2] += dt_routing
        elsif dn_full
          @ctx_.links.stat_time_full_dnstream.a[uj_2] += dt_routing
        end
        dw = @ctx_.options.routing_model == 2
        if dw ? ((fs & 4) != 0) : up_full
          cap_ltd = true
          if ((dw || (@ctx_.options.routing_model == 3)) && (n1 >= 0)) && (n2 >= 0)
            h1h = @ctx_.nodes.head.a[n1 < 0 ? n1 + 0x10000000000000000 : n1]
            h2h = @ctx_.nodes.head.a[n2 < 0 ? n2 + 0x10000000000000000 : n2]
            len = (cr_2 >= 0) ? _CD.length.a[cr_2 < 0 ? cr_2 + 0x10000000000000000 : cr_2] : 0.0
            slp = ((cr_2 >= 0) ? _CD.slope.a[cr_2 < 0 ? cr_2 + 0x10000000000000000 : cr_2] : 0.0).abs
            cap_ltd = (h1h - h2h) > (slp * len)
          end
          if cap_ltd
            @ctx_.links.stat_time_capacity_limited.a[uj_2] += dt_routing
          end
        end
      end
      crs = @ctx_.link_subtypes.conduit_row(j_2)
      if crs >= 0
        ucrs = crs < 0 ? crs + 0x10000000000000000 : crs
        _CDs = @ctx_.link_subtypes.conduits
        if _CDs.normal_flow_limited.a[ucrs] != 0
          @ctx_.links.stat_norm_ltd.a[uj_2] += dt_routing
