  def writeHotstartSave(entry)
    sp = (!(entry.path.absolute.n == 0)) ? entry.path.absolute : entry.path.original
    if sp.n == 0
      return
    end
    lid_restart = Algo_any_of(@ctx_.node_subtypes.storages.lid.begin(), @ctx_.node_subtypes.storages.lid.end(), ->(c) { c.control >= 0 })
    full_continuation = @ctx_.options.heat_transport
    native = (entry.format_ == 2) || ((entry.format_ == 0) && (lid_restart || full_continuation))
    rc = 0
    if native
      hs = Cpp::Cell.new(nil)
      if full_continuation && @checkpoint_enabled_
        snapshot = NewStr()
        error = self.checkpointBytes(snapshot, false)
        if !(error.n == 0)
          @ctx_.warnings.push_back(Str_Cat_CPtr_Str(R_Lit("SAVE HOTSTART: incomplete native continuation: "), error))
          return
        end
        Mv_Reset(hs, HotStartManager_save_with_engine_checkpoint(@ctx_, @runoff_, @groundwater_, sp, snapshot))
      else
        Mv_Reset(hs, HotStartManager_save(@ctx_, sp))
      end
      rc = (!hs.v.nil?) ? 0 : 1
    else
      if lid_restart
        @ctx_.warnings.push_back(Str_Cat_Str_CPtr(Str_Cat_CPtr_Str(R_Lit("SAVE HOTSTART: '"), sp), R_Lit("' is LEGACY; a legacy SWMM5 file carries no LID state.")))
      end
      runoff = self.legacyRunoffSection()
      rc = HotStartManager_save_legacy_routing(sp, @ctx_, runoff)
    end
    if rc != 0
      @ctx_.warnings.push_back(Str_Cat_CPtr_Str(R_Lit("SAVE HOTSTART: "), HotStartManager_last_io_error()))
    end
  end

  def writeDueHotstartSaves
    k = 0
    while k < @ctx_.files.hotstart_saves.n
      entry = @ctx_.files.hotstart_saves.a[k]
      if ((entry.datetime == 0.0) || (k >= @hotstart_save_done_.n)) || (@hotstart_save_done_.a[k] != 0)
        k += 1
        next
      end
      due_ms = (entry.datetime - @ctx_.options.start_date) * 86400000.0
      if (@ctx_.elapsed_ms + 1.0) < due_ms
        k += 1
        next
      end
      @hotstart_save_done_.a[k] = 1
      self.writeHotstartSave(entry)
      k += 1
    end
  end

