      end
      name = @ctx_.subcatches.outlet_name.a[us]
      if ((!(name.n == 0)) && (@ctx_.node_names.find(name.Clone()) >= 0)) && (@ctx_.subcatch_names.find(name.Clone()) >= 0)
        @ctx_.errors.push_back(F_format_error__i_sv(108, @ctx_.subcatch_names.name_of(s).Clone()))
      end
      s += 1
    end
    ng = @ctx_.n_gages()
    g = 0
