      end
      ts = @ctx_.gages.ts_index.a[ug]
      if (ts >= 0) && (ts < ((@ctx_.tables.tables.n + 0x80000000 & 0xFFFFFFFF) - 0x80000000))
        tx = @ctx_.tables.tables.a[ts < 0 ? ts + 0x10000000000000000 : ts].x
        if tx.n > 1
          dx_min = tx.a[1] - tx.a[0]
          k = 2
          while k < tx.n
            dx_min = (_m1 = tx.a[k] - tx.a[(k - 1) & 0xFFFFFFFFFFFFFFFF]; _m1 < dx_min ? _m1 : dx_min)
            k += 1
          end
          ts_interval = Conv_D2I(Math_Floor_d((dx_min * 86400.0) + 0.5))
          if (ts_interval > 0) && (@ctx_.gages.interval_sec.a[ug] > ts_interval)
            @ctx_.errors.push_back(F_format_error__i_sv(159, @ctx_.gage_names.name_of(g).Clone()))
          end
          if @ctx_.gages.interval_sec.a[ug] < ts_interval
            @ctx_.warnings.push_back(F_format_warning__i_sv(9, @ctx_.gage_names.name_of(g).Clone()))
          end
        end
