    end
  end

  def checkRoutingDiverged
    kAbsurd = 1000000000.0
    diverged = ->(v) { (!v.finite?) || (v.abs > kAbsurd) }
    s = @router_.fvSolver()
    if !s.nil?
      dv = fv_INetworkSolver_Divergence__new()
      if s.divergence(dv)
        buf = R_Buf_i(256)
        R_snprintf_CPtr_ul_CPtr_oA(buf, 256, R_Lit("ERROR %d: the FV solution diverged in conduit '%s' (%s %.6g) after %.4f hours -- a step-size-independent instability the substep retry cannot shrink away; the run cannot continue."), 14, (dv.link >= 0) ? @ctx_.link_names.name_of(dv.link).c_str() : R_Lit("?"), (!dv.what.get_IsNull()) ? dv.what : R_Lit("state"), dv.value, @ctx_.current_time / 3600.0)
        @ctx_.errors.push_back(NewStr_CPtr(buf))
        self.set_error(14, buf)
        return 14
      end
    end
    nn = @ctx_.n_nodes()
    i = 0
    i = 0
    while i < nn
      ui = i
      if !diverged.call(@ctx_.nodes.head.a[ui])
        i += 1
        next
      end
      buf_2 = R_Buf_i(256)
      R_snprintf_CPtr_ul_CPtr_oA(buf_2, 256, R_Lit("ERROR %d: the routing solution diverged at node '%s' (head %.6g) after %.4f hours -- the run cannot continue."), 14, @ctx_.node_names.name_of(i).c_str(), @ctx_.nodes.head.a[ui], @ctx_.current_time / 3600.0)
      @ctx_.errors.push_back(NewStr_CPtr(buf_2))
      self.set_error(14, buf_2)
      return 14
    end
    nl = @ctx_.n_links()
    j = 0
    j = 0
    while j < nl
      uj = j
      if !diverged.call(@ctx_.links.flow.a[uj])
        j += 1
        next
      end
      buf_3 = R_Buf_i(256)
      R_snprintf_CPtr_ul_CPtr_oA(buf_3, 256, R_Lit("ERROR %d: the routing solution diverged at link '%s' (flow %.6g) after %.4f hours -- the run cannot continue."), 14, @ctx_.link_names.name_of(j).c_str(), @ctx_.links.flow.a[uj], @ctx_.current_time / 3600.0)
      @ctx_.errors.push_back(NewStr_CPtr(buf_3))
      self.set_error(14, buf_3)
      return 14
    end
    return 0
  end

  def write_open_failure_report
    if (@rpt_path_.n == 0) || @ctx_.options.rpt_disabled
      return
    end
    begin
      rp = DefaultReportPlugin_New_str(@rpt_path_.Clone())
      __dtor1 = NewDefer(-> { Dtor_Run(rp); nil })
      begin
        rp.initialize_(NewVec(K_MK4), nil)
        rp.prepare(@ctx_)
        rp.finalize(@ctx_)
      ensure
        __dtor1.Dispose() unless __dtor1.nil?
      end
    rescue StandardError => __ex2
      Dbg_Caught(__ex2)
    end
  end

  def set_error(code, message)
    @ctx_.error_code = code
    @ctx_.error_message.Assign_CPtr((!message.get_IsNull()) ? message : R_Lit(""))
    @ctx_.state = 8
    self.emit_warning(code, message)
  end

  def emit_warning(code, message)
    if !@callbacks_.on_warning.nil?
      @callbacks_.on_warning.call(self, code, message, @callbacks_.warning_ud)
    end
  end

  def push_report_warning(message, code)
    begin
      @ctx_.warnings.push_back(message.Clone())
    rescue StandardError => __ex1
      Dbg_Caught(__ex1)
    end
    self.emit_warning(code, message.c_str())
  end

  def emit_progress
    if !(!@callbacks_.on_progress.nil?)
      return
    end
    total = (@ctx_.options.end_date - @ctx_.options.start_date) * $hydraulics_TimestepController_SEC_PER_DAY
    frac = (total > 0.0) ? (total != 0.0 ? @ctx_.current_time / total : fdiv0(@ctx_.current_time, total)) : 0.0
    @callbacks_.on_progress.call(self, frac, @ctx_.current_date, @callbacks_.progress_ud)
  end

