  def refreshReportedSpecies
    @reported_species_names.clear()
    p = 0
    while p < self.n_pollutants()
      @reported_species_names.push_back(@pollutant_names.name_of(p).Clone())
      p += 1
    end
    if @options.water_age
      @reported_species_names.push_back(NewStr_CPtr(R_Lit("__WATER_AGE__")))
    end
    if @options.heat_transport
      @reported_species_names.push_back(NewStr_CPtr(R_Lit("__TEMPERATURE__")))
    end
    @reactions.reported_species.clear()
    m = 0
    while m < @reactions.n_species()
      if (!(@reactions.report_enabled.n == 0)) && (!(@reactions.report_enabled.a[m < 0 ? m + 0x10000000000000000 : m] != 0))
        m += 1
        next
      end
      @reactions.reported_species.push_back(m)
      @reported_species_names.push_back(@reactions.species_name.a[m < 0 ? m + 0x10000000000000000 : m].Clone())
      m += 1
    end
  end

  def n_reported_species
    return (@reported_species_names.n + 0x80000000 & 0xFFFFFFFF) - 0x80000000
  end

  def logControlAction(e)
    if @control_log.n >= $SimulationContext_kMaxControlLog
      @control_log_dropped = (@control_log_dropped + 1) & 0xFFFFFFFFFFFFFFFF
      return
    end
    @control_log.push_back(e.Clone())
  end

  def finalize_max_stats
    k = 0
    k = 0
    _n1 = $SimulationContext_MAX_STATS
    while k < _n1
      _o2 = SimulationContext_MaxStats__new()
      _o2.obj_type = 0
      _o2.index = -1
      _o2.value = -1.0
      @max_courant_crit[k].MoveFrom(_o2)
      _o3 = SimulationContext_MaxStats__new()
      _o3.obj_type = 1
      _o3.index = -1
      _o3.value = -1.0
      @max_flow_turns[k].MoveFrom(_o3)
      _o4 = SimulationContext_MaxStats__new()
      _o4.obj_type = 0
      _o4.index = -1
      _o4.value = 0.0
      @max_non_converged[k].MoveFrom(_o4)
      k += 1
    end
    rpt_steps = @routing_stats.report_steps
    if rpt_steps > 2
      z = (_d5 = 0.6666666666666666 * (((rpt_steps - 2) + 0x8000000000000000 & 0xFFFFFFFFFFFFFFFF) - 0x8000000000000000).to_f) != 0.0 ? 100.0 / _d5 : fdiv0(100.0, _d5)
      j = 0
      while j < self.n_links()
        x = @links.stat_flow_turns.a[j < 0 ? j + 0x10000000000000000 : j].to_f * z
        SimulationContext_updateMaxStats(NewPtr_TA_l(@max_flow_turns, 0), 1, j, x)
        j += 1
      end
    end
    step_count = @routing_stats.n_steps
    dw = @options.routing_model == 2
    if dw
      j_2 = 0
      while j_2 < self.n_nodes()
        SimulationContext_updateMaxStats(NewPtr_TA_l(@max_non_converged, 0), 0, j_2, (_n7 = @nodes.stat_non_converged_count.a[j_2 < 0 ? j_2 + 0x10000000000000000 : j_2]; (_d6 = step_count.to_f) != 0.0 ? _n7 / _d6 : fdiv0(_n7, _d6)))
        j_2 += 1
      end
    end
    if ((!dw) || (@options.variable_step == 0.0)) || (step_count == 0)
      return
    end
    inv_steps = step_count.to_f != 0.0 ? 1.0 / step_count.to_f : fdiv0(1.0, step_count.to_f)
    j_3 = 0
    while j_3 < self.n_nodes()
      x_2 = @nodes.stat_time_courant_critical.a[j_3 < 0 ? j_3 + 0x10000000000000000 : j_3] * inv_steps
      SimulationContext_updateMaxStats(NewPtr_TA_l(@max_courant_crit, 0), 0, j_3, 100.0 * x_2)
      j_3 += 1
    end
    j_4 = 0
    while j_4 < self.n_links()
      x_3 = @links.stat_time_courant_critical.a[j_4 < 0 ? j_4 + 0x10000000000000000 : j_4] * inv_steps
      SimulationContext_updateMaxStats(NewPtr_TA_l(@max_courant_crit, 0), 1, j_4, 100.0 * x_3)
      j_4 += 1
    end
  end

