  def linkValidateRoutingStep
    return ((@routing_step_authored > 0.0) ? FR_SimulationOptions_routing_step_authored.new(self) : FR_SimulationOptions_routing_step.new(self)).v
  end

  def totalDurationMs
    if @total_duration_ms >= 0.0
      return @total_duration_ms
    end
    return Math_Floor_d((@end_date - @start_date) * 86400.0) * 1000.0
  end
