    @node_over_temp = s.node_over_temp
    s.node_over_temp = NewVecD()
  end

  def source_temp(s, node)
    i = 0
    while i < @node_over_source.n
      if (@node_over_source.a[i] == s) && (@node_over_node.a[i] == node)
        return @node_over_temp.a[i]
      end
      i += 1
    end
    return @global_temp[s]
  end
