    s.subarea_vol_prev = NewVecD()
    @subcatch_runoff_temp = s.subcatch_runoff_temp
    s.subcatch_runoff_temp = NewVecD()
    @subcatch_runon_temp_vol_in = s.subcatch_runon_temp_vol_in
    s.subcatch_runon_temp_vol_in = NewVecD()
    @subcatch_runon_temp_rate = s.subcatch_runon_temp_rate
    s.subcatch_runon_temp_rate = NewVecD()
    @subcatch_outfall_temp_vol = s.subcatch_outfall_temp_vol
    s.subcatch_outfall_temp_vol = NewVecD()
    @subcatch_lid_drain_temp_cfs = s.subcatch_lid_drain_temp_cfs
    s.subcatch_lid_drain_temp_cfs = NewVecD()
  end

  def resize(n_nodes, n_links, initial_temp)
    @node_temp_vol_in.assign_ul_T(n_nodes < 0 ? n_nodes + 0x10000000000000000 : n_nodes, 0.0)
    @node_lid_drain_temp_vol_in.assign_ul_T(n_nodes < 0 ? n_nodes + 0x10000000000000000 : n_nodes, 0.0)
    @node_temp.assign_ul_T(n_nodes < 0 ? n_nodes + 0x10000000000000000 : n_nodes, initial_temp)
    @link_temp.assign_ul_T(n_links < 0 ? n_links + 0x10000000000000000 : n_links, initial_temp)
    @legacy_seeded = false
    @shortwave_now = -1.0
    @cloud_now = 0.0
  end

  def resizeWatershed(n_subcatch, initial_temp)
    n = n_subcatch < 0 ? n_subcatch + 0x10000000000000000 : n_subcatch
    @subarea_temp.assign_ul_T((n * ($HeatState_kNSubArea < 0 ? $HeatState_kNSubArea + 0x10000000000000000 : $HeatState_kNSubArea)) & 0xFFFFFFFFFFFFFFFF, initial_temp)
    @subarea_vol_prev.assign_ul_T((n * ($HeatState_kNSubArea < 0 ? $HeatState_kNSubArea + 0x10000000000000000 : $HeatState_kNSubArea)) & 0xFFFFFFFFFFFFFFFF, 0.0)
    @subcatch_runoff_temp.assign_ul_T(n, initial_temp)
    @subcatch_runon_temp_vol_in.assign_ul_T(n, 0.0)
    @subcatch_runon_temp_rate.assign_ul_T(n, 0.0)
    @subcatch_outfall_temp_vol.assign_ul_T(n, 0.0)
    @subcatch_lid_drain_temp_cfs.assign_ul_T(n, 0.0)
  end

  def watershedSized(n_subcatch)
    return @subarea_temp.n == (((n_subcatch < 0 ? n_subcatch + 0x10000000000000000 : n_subcatch) * ($HeatState_kNSubArea < 0 ? $HeatState_kNSubArea + 0x10000000000000000 : $HeatState_kNSubArea)) & 0xFFFFFFFFFFFFFFFF)
  end

  def clear
    _o1 = HeatState__new()
    _o1.mesh_contact_link = NewVecB()
    _o1.node_temp_vol_in = NewVecD()
    _o1.node_lid_drain_temp_vol_in = NewVecD()
    _o1.node_temp = NewVecD()
    _o1.link_temp = NewVecD()
    _o1.subarea_temp = NewVecD()
    _o1.subarea_vol_prev = NewVecD()
    _o1.subcatch_runoff_temp = NewVecD()
    _o1.subcatch_runon_temp_vol_in = NewVecD()
    _o1.subcatch_runon_temp_rate = NewVecD()
    _o1.subcatch_outfall_temp_vol = NewVecD()
    _o1.subcatch_lid_drain_temp_cfs = NewVecD()
    self.MoveFrom(_o1)
  end
end

