      return
    end
    @names = s.names
    s.names = NewVec(K_MK4)
    @types = s.types
    s.types = NewVecI()
    @factors = s.factors
    s.factors = NewVec(K_MK38)
  end

  def count
    return (@names.n + 0x80000000 & 0xFFFFFFFF) - 0x80000000
  end

  def add(name, type, facs)
    @names.push_back(name.Clone())
    @types.push_back(type)
    @factors.push_back(facs.Clone())
  end

  def find(name)
    i = 0
    while i < self.count()
      if F_ieq(@names.a[i < 0 ? i + 0x10000000000000000 : i].Clone(), name.Clone())
        return i
      end
      i += 1
    end
    return -1
  end
