  end

  def find_by_link(link_idx)
    i = 0
    while i < self.count()
      if @link_index.a[i < 0 ? i + 0x10000000000000000 : i] == link_idx
        return i
      end
      i += 1
    end
    return -1
  end

  def find_by_node_host(node_idx)
    i = 0
    while i < self.count()
      if @node_host.a[i < 0 ? i + 0x10000000000000000 : i] == node_idx
        return i
      end
      i += 1
    end
    return -1
  end

  def resize_stats(n)
    un = n < 0 ? n + 0x10000000000000000 : n
    @stat_capture_vol.assign_ul_T(un, 0.0)
    @stat_bypass_vol.assign_ul_T(un, 0.0)
    @stat_backflow_vol.assign_ul_T(un, 0.0)
