  def add_lstep_sample(j, dt, dur, rs)
    u = j < 0 ? j + 0x10000000000000000 : j
    if (@stat_lstep_time.a[u] <= 0.0) || (dt < @stat_lstep_min.a[u])
      @stat_lstep_min.a[u] = dt
    end
    if dt > @stat_lstep_max.a[u]
      @stat_lstep_max.a[u] = dt
    end
    @stat_lstep_dt_time.a[u] += dt * dur
    @stat_lstep_time.a[u] += dur
    @stat_lstep_bin_time.a[((u * ($LinkData_N_LSTEP_BINS < 0 ? $LinkData_N_LSTEP_BINS + 0x10000000000000000 : $LinkData_N_LSTEP_BINS)) + ((_u1 = LinkData_lstep_bin(dt, rs)) < 0 ? _u1 + 0x10000000000000000 : _u1)) & 0xFFFFFFFFFFFFFFFF] += dur
  end

  def count
    return (@type.n + 0x80000000 & 0xFFFFFFFF) - 0x80000000
  end

