class DividerData
  include Cpp::ICopy
  attr_accessor :node_idx, :method_, :cutoff, :cd, :max_depth, :curve, :link, :link_name, :curve_name

  def initialize
    @node_idx = nil
    @method_ = nil
    @cutoff = nil
    @cd = nil
    @max_depth = nil
    @curve = nil
    @link = nil
    @link_name = nil
    @curve_name = nil
  end

  def __init_rDividerData(p)
    @node_idx = p.node_idx.Clone()
    @method_ = p.method_.Clone()
    @cutoff = p.cutoff.Clone()
    @cd = p.cd.Clone()
    @max_depth = p.max_depth.Clone()
    @curve = p.curve.Clone()
    @link = p.link.Clone()
    @link_name = p.link_name.Clone()
    @curve_name = p.curve_name.Clone()
  end

  def __init_mDividerData(p)
    self.MoveFrom(p)
  end

  def __init_d
    @node_idx = NewVecI()
    @method_ = NewVecB()
    @cutoff = NewVecD()
    @cd = NewVecD()
    @max_depth = NewVecD()
    @curve = NewVecI()
    @link = NewVecI()
    @link_name = NewVec(K_MK4)
    @curve_name = NewVec(K_MK4)
  end

  def ctor_DividerData
    self.__init_d()
  end

  def Clone
    o = DividerData.new
    o.__CopyFrom_DividerData(self)
    return o
  end

  def __CopyFrom_DividerData(s)
    @node_idx = s.node_idx.nil? ? nil : s.node_idx.Clone()
    @method_ = s.method_.nil? ? nil : s.method_.Clone()
    @cutoff = s.cutoff.nil? ? nil : s.cutoff.Clone()
    @cd = s.cd.nil? ? nil : s.cd.Clone()
    @max_depth = s.max_depth.nil? ? nil : s.max_depth.Clone()
    @curve = s.curve.nil? ? nil : s.curve.Clone()
    @link = s.link.nil? ? nil : s.link.Clone()
    @link_name = s.link_name.nil? ? nil : s.link_name.Clone()
    @curve_name = s.curve_name.nil? ? nil : s.curve_name.Clone()
  end

  def Assign(s)
    if self.equal?(s)
      return
    end
    @node_idx.Assign_VecT(s.node_idx)
    @method_.Assign_VecT(s.method_)
    @cutoff.Assign_VecT(s.cutoff)
    @cd.Assign_VecT(s.cd)
    @max_depth.Assign_VecT(s.max_depth)
    @curve.Assign_VecT(s.curve)
    @link.Assign_VecT(s.link)
    @link_name.Assign_VecT(s.link_name)
    @curve_name.Assign_VecT(s.curve_name)
  end

  def MoveFrom(s)
    if self.equal?(s)
      return
    end
    @node_idx = s.node_idx
    s.node_idx = NewVecI()
    @method_ = s.method_
    s.method_ = NewVecB()
    @cutoff = s.cutoff
    s.cutoff = NewVecD()
    @cd = s.cd
    s.cd = NewVecD()
    @max_depth = s.max_depth
    s.max_depth = NewVecD()
    @curve = s.curve
