      return
    end
    @storages = s.storages
    s.storages = StorageData__new()
    @outfalls = s.outfalls
    s.outfalls = OutfallData__new()
    @dividers = s.dividers
    s.dividers = DividerData__new()
    @subtype_row = s.subtype_row
    s.subtype_row = NewVecI()
  end

  def clear
    @storages.clear()
    @outfalls.clear()
    @dividers.clear()
    @subtype_row.clear()
  end

  def rebuild_index(n_nodes)
    @subtype_row.assign_ul_T(n_nodes < 0 ? n_nodes + 0x10000000000000000 : n_nodes, -1)
    r = 0
    while r < @storages.count()
      @subtype_row.a[(_u1 = @storages.node_idx.a[r < 0 ? r + 0x10000000000000000 : r]) < 0 ? _u1 + 0x10000000000000000 : _u1] = r
      r += 1
    end
    r_2 = 0
    while r_2 < @outfalls.count()
      @subtype_row.a[(_u2 = @outfalls.node_idx.a[r_2 < 0 ? r_2 + 0x10000000000000000 : r_2]) < 0 ? _u2 + 0x10000000000000000 : _u2] = r_2
      r_2 += 1
    end
    r_3 = 0
    while r_3 < @dividers.count()
      @subtype_row.a[(_u3 = @dividers.node_idx.a[r_3 < 0 ? r_3 + 0x10000000000000000 : r_3]) < 0 ? _u3 + 0x10000000000000000 : _u3] = r_3
      r_3 += 1
    end
  end

  def set_node_type(nodes, i, t)
    ui = i < 0 ? i + 0x10000000000000000 : i
    if i >= ((@subtype_row.n + 0x80000000 & 0xFFFFFFFF) - 0x80000000)
      @subtype_row.resize_ul_T(((i < 0 ? i + 0x10000000000000000 : i) + 1) & 0xFFFFFFFFFFFFFFFF, -1)
    end
    if (t != 0) && (ui < nodes.storage_area.n)
      nodes.storage_area.a[ui] = 0.0
    end
    old = nodes.type.a[ui]
    existing = @subtype_row.a[ui]
    if (old == t) && (existing >= 0)
      return existing
    end
    shifted = false
    if existing >= 0
      case old
      when 3
        @storages.erase_at(existing)
      when 1
        @outfalls.erase_at(existing)
      when 2
        @dividers.erase_at(existing)
      else
      end
      shifted = true
    end
    nodes.type.a[ui] = t
    row = -1
    case t
    when 3
      row = @storages.add_default(i)
      if row != (((@storages.count() - 1) + 0x80000000 & 0xFFFFFFFF) - 0x80000000)
        shifted = true
      end
    when 1
      row = @outfalls.add_default(i)
      if row != (((@outfalls.count() - 1) + 0x80000000 & 0xFFFFFFFF) - 0x80000000)
        shifted = true
      end
    when 2
      row = @dividers.add_default(i)
      if row != (((@dividers.count() - 1) + 0x80000000 & 0xFFFFFFFF) - 0x80000000)
        shifted = true
      end
    when 0
    else
    end
    if shifted
      self.rebuild_index(nodes.count())
      return (t == 0) ? (-1) : @subtype_row.a[ui]
    end
    @subtype_row.a[ui] = row
    return row
  end

  def storage_row(i)
    if (i >= 0) && (i < ((@subtype_row.n + 0x80000000 & 0xFFFFFFFF) - 0x80000000))
      r = @subtype_row.a[i < 0 ? i + 0x10000000000000000 : i]
      if ((r >= 0) && (r < @storages.count())) && (@storages.node_idx.a[r < 0 ? r + 0x10000000000000000 : r] == i)
        return r
      end
    end
    return -1
  end

  def outfall_row(i)
    if (i >= 0) && (i < ((@subtype_row.n + 0x80000000 & 0xFFFFFFFF) - 0x80000000))
      r = @subtype_row.a[i < 0 ? i + 0x10000000000000000 : i]
      if ((r >= 0) && (r < @outfalls.count())) && (@outfalls.node_idx.a[r < 0 ? r + 0x10000000000000000 : r] == i)
        return r
      end
    end
    return -1
  end

  def divider_row(i)
    if (i >= 0) && (i < ((@subtype_row.n + 0x80000000 & 0xFFFFFFFF) - 0x80000000))
      r = @subtype_row.a[i < 0 ? i + 0x10000000000000000 : i]
      if ((r >= 0) && (r < @dividers.count())) && (@dividers.node_idx.a[r < 0 ? r + 0x10000000000000000 : r] == i)
        return r
      end
    end
    return -1
  end
end

