class SpeciesRegistry
  include Cpp::ICopy
  attr_accessor :name_, :kind_, :units_, :n_pollutants_

  def initialize
    @name_ = nil
    @kind_ = nil
    @units_ = nil
    @n_pollutants_ = 0
  end

  def __init_rSpeciesRegistry(p)
    @name_ = p.name_.Clone()
    @kind_ = p.kind_.Clone()
    @units_ = p.units_.Clone()
    @n_pollutants_ = p.n_pollutants_
  end

  def __init_mSpeciesRegistry(p)
    self.MoveFrom(p)
  end

  def __init_d
    @name_ = NewVec(K_MK4)
    @kind_ = NewVecI()
    @units_ = NewVec(K_MK4)
    @n_pollutants_ = 0
  end

  def ctor_SpeciesRegistry
    self.__init_d()
  end

  def Clone
    o = SpeciesRegistry.new
    o.__CopyFrom_SpeciesRegistry(self)
    return o
  end

  def __CopyFrom_SpeciesRegistry(s)
    @name_ = s.name_.nil? ? nil : s.name_.Clone()
    @kind_ = s.kind_.nil? ? nil : s.kind_.Clone()
    @units_ = s.units_.nil? ? nil : s.units_.Clone()
    @n_pollutants_ = s.n_pollutants_
  end

  def Assign(s)
    if self.equal?(s)
      return
    end
    @name_.Assign_VecT(s.name_)
    @kind_.Assign_VecT(s.kind_)
    @units_.Assign_VecT(s.units_)
    @n_pollutants_ = s.n_pollutants_
  end

  def MoveFrom(s)
    if self.equal?(s)
      return
    end
    @name_ = s.name_
    s.name_ = NewVec(K_MK4)
    @kind_ = s.kind_
    s.kind_ = NewVecI()
    @units_ = s.units_
    s.units_ = NewVec(K_MK4)
    @n_pollutants_ = s.n_pollutants_
  end

  def clear
    @name_.clear()
    @kind_.clear()
    @units_.clear()
    @n_pollutants_ = 0
  end

  def add(name, kind, units)
    name = Cpp::Cell.new(name)
    units = Cpp::Cell.new(units)
    if self.find(name.v.Clone()) >= 0
      return -1
    end
    @name_.push_back(Mv_Take(name, K_MK4))
    @kind_.push_back(kind)
    @units_.push_back(Mv_Take(units, K_MK4))
    if kind == 0
      @n_pollutants_ += 1
    end
    return ((((@name_.n + 0x80000000 & 0xFFFFFFFF) - 0x80000000) - 1) + 0x80000000 & 0xFFFFFFFF) - 0x80000000
  end

  def find(name)
    i = 0
    while i < @name_.n
      if name.Clone().Equals_Str(@name_.a[i].Clone())
        return (i + 0x80000000 & 0xFFFFFFFF) - 0x80000000
      end
      i += 1
    end
    return -1
  end

  def pollutant_count
    return @n_pollutants_
  end

  def name(i)
    return @name_.a[i < 0 ? i + 0x10000000000000000 : i]
  end
end

