  def resize_total_load(n_sc, n_poll)
    @total_load_n_pollutants = n_poll
    @total_load.assign_ul_T(((n_sc < 0 ? n_sc + 0x10000000000000000 : n_sc) * (n_poll < 0 ? n_poll + 0x10000000000000000 : n_poll)) & 0xFFFFFFFFFFFFFFFF, 0.0)
  end

  def count
    return (@area.n + 0x80000000 & 0xFFFFFFFF) - 0x80000000
  end

