  def grow_to(n)
    if n <= self.count()
      return
    end
    un = n < 0 ? n + 0x10000000000000000 : n
    g = [->(vec, def_) { vec.resize_ul_T(un, def_); nil }, ->(vec_2, def_2) { vec_2.resize_ul_T(un, def_2); nil }, ->(vec_3, def_3) { vec_3.resize_ul_T(un, def_3); nil }]
    g[0].call(@outlet_node, -1)
    g[0].call(@outlet_subcatch, -1)
    @outlet_name.resize_ul(un)
    @snowpack_name.resize_ul(un)
    @gage_name.resize_ul(un)
    g[0].call(@gage, -1)
    g[1].call(@area, 0.0)
