    yNorm = y_full != 0.0 ? y / y_full : fdiv0(y, y_full)
    if yNorm < $F_constants_SLOT_CROWN_CUTOFF
      return 0.0
    end
    if yNorm > 1.78
      return 0.01 * w_max
    end
    return (w_max * 0.5423) * Math_Exp_d(-Math_Pow_d(yNorm, 2.4))
  end

  def getCrownCutoff
    if ((@surcharge_method == 1) || (@surcharge_method == 2)) || (@surcharge_method == 3)
      return $F_constants_SLOT_CROWN_CUTOFF
    end
    return $F_constants_EXTRAN_CROWN_CUTOFF
  end

  def applyDPSGeometry(ctx)
    links = ctx.links
    ci = 0
    ci = 0
    _n1 = @n_conduits_
    while ci < _n1
      j = @conduit_idx_.a[ci]
      uj = j < 0 ? j + 0x10000000000000000 : j
      uci = ci
      if @is_open_.a[uj] != 0
        ci += 1
        next
      end
      yf = links.xsect_y_full.a[uj]
      af = links.xsect_a_full.a[uj]
      rf = links.xsect_r_full.a[uj]
      if (yf <= 0.0) || (af <= 0.0)
        ci += 1
        next
      end
      y1 = @depth1_.a[uj]
      y2 = @depth2_.a[uj]
      yMid = @depth_mid_.a[uj]
      hs_iter = (yMid > yf) ? (yMid - yf) : 0.0
      hs_prev = @dps_.hs_prev_iter.a[uci]
      dhs = hs_iter - hs_prev
      _P = @dps_.P.a[uci]
      _Ts = (@dps_.T_s_target.a[uci] * _P) * _P
      _As_new = @dps_.As.a[uci] + (_Ts * dhs)
      if _As_new < 0.0
        _As_new = 0.0
      end
      slot_active = (hs_iter > 0.0) || (_As_new > 0.0)
      @dps_.As.a[uci] = _As_new
      @dps_.hs.a[uci] = hs_iter
      @dps_.hs_prev_iter.a[uci] = hs_iter
      if !slot_active
        ci += 1
        next
      end
      _A_total = af + _As_new
      @area_mid_.a[uj] = _A_total
      if y1 > yf
        @area1_.a[uj] = _A_total
      end
      if y2 > yf
        @area2_.a[uj] = _A_total
      end
      @width_mid_.a[uj] = _Ts
      _L = @cached_length_.a[uj]
      slot_surf_per_end = (0.25 * _Ts) * _L
      if y1 > yf
        @surf_area1_.a[uj] = slot_surf_per_end
      end
      if y2 > yf
        @surf_area2_.a[uj] = slot_surf_per_end
      end
      @hrad_mid_.a[uj] = rf
      ci += 1
    end
  end

  def updateTpaLatch(ctx)
    links = ctx.links
    nodes = ctx.nodes
    kCavHead = 30.0
    ci = 0
    ci = 0
    _n1 = @n_conduits_
    while ci < _n1
      uci = ci
      j = @conduit_idx_.a[uci]
      uj = j < 0 ? j + 0x10000000000000000 : j
      @tpa_latch_changed_.a[uci] = 0
      if @is_open_.a[uj] != 0
        @tpa_latch_.a[uci] = 0
        ci += 1
        next
      end
      yf = links.xsect_y_full.a[uj]
      if yf <= 0.0
        @tpa_latch_.a[uci] = 0
        ci += 1
        next
      end
      y1 = @depth1_.a[uj]
      y2 = @depth2_.a[uj]
      old = @tpa_latch_.a[uci]
      latched = old
      if !(old != 0)
        latched = ((y1 >= yf) && (y2 >= yf)) ? 1 : 0
      else
        yMid = @depth_mid_.a[uj]
        if yMid < (yf - kCavHead)
          latched = 0
        else
          _lam2 = ->(yf) do
            ->(n, y_end) do
              if n < 0
                return false
              end
              un2 = n < 0 ? n + 0x10000000000000000 : n
              sealed = ((un2 < nodes.is_virtual.n) && (nodes.is_virtual.a[un2] != 0)) || ((un2 < nodes.sur_depth.n) && (nodes.sur_depth.a[un2] > 0.0))
              return (!sealed) && (y_end < yf)
            end
          end.(yf)
          vented_end = _lam2
          if vented_end.call(links.node1.a[uj], y1) || vented_end.call(links.node2.a[uj], y2)
            latched = 0
          end
        end
      end
      @tpa_latch_.a[uci] = latched
      @tpa_latch_changed_.a[uci] = (latched != old) ? 1 : 0
      ci += 1
    end
  end

  def applyTpaGeometry(ctx)
    links = ctx.links
    ci = 0
    ci = 0
    _n1 = @n_conduits_
    while ci < _n1
      uci = ci
      j = @conduit_idx_.a[uci]
      uj = j < 0 ? j + 0x10000000000000000 : j
      if @is_open_.a[uj] != 0
        ci += 1
        next
      end
      yf = links.xsect_y_full.a[uj]
      af = links.xsect_a_full.a[uj]
      rf = links.xsect_r_full.a[uj]
      if (yf <= 0.0) || (af <= 0.0)
        ci += 1
        next
      end
      w = @tpa_w_.a[uci]
      if w <= 0.0
        ci += 1
        next
      end
      yMid = @depth_mid_.a[uj]
      engaged = (@tpa_latch_.a[uci] != 0) || (yMid >= ($F_constants_SLOT_CROWN_CUTOFF * yf))
      if !engaged
        ci += 1
        next
      end
      line_area = ->(af, w, yf) { ->(y) { (_m2 = af + (w * (y - yf)); _m3 = 0.05 * af; _m2 < _m3 ? _m3 : _m2) } }.(af, w, yf)
      @area_mid_.a[uj] = line_area.call(yMid)
      @area1_.a[uj] = line_area.call(@depth1_.a[uj])
      @area2_.a[uj] = line_area.call(@depth2_.a[uj])
      @width_mid_.a[uj] = w
      _L = @cached_length_.a[uj]
      slot_surf_per_end = (0.25 * w) * _L
      @surf_area1_.a[uj] = slot_surf_per_end
      @surf_area2_.a[uj] = slot_surf_per_end
      @hrad_mid_.a[uj] = rf
      ci += 1
    end
  end

  def updateDPSState(ctx, dt)
    links = ctx.links
    @sim_time_ += dt
    ci = 0
    ci = 0
    _n1 = @n_conduits_
    while ci < _n1
      j = @conduit_idx_.a[ci]
      uj = j < 0 ? j + 0x10000000000000000 : j
      uci = ci
      if @is_open_.a[uj] != 0
        ci += 1
        next
      end
      yf = links.xsect_y_full.a[uj]
      was_surcharged = @dps_.surcharged.a[uci] != 0
      now_surcharged = (@depth_mid_.a[uj] > yf) && (@dps_.As.a[uci] > 0.0)
      if now_surcharged && (!was_surcharged)
        @dps_.t_s.a[uci] = @sim_time_
      end
      if now_surcharged
        dt_surcharge = @sim_time_ - @dps_.t_s.a[uci]
        @dps_.P_hat.a[uci] = ((@dps_.P_hat_0.a[uci] - 1.0) * Math_Exp_d((_n3 = (-10.0) * dt_surcharge; (_d2 = @dps_config_.r) != 0.0 ? _n3 / _d2 : fdiv0(_n3, _d2)))) + 1.0
      else
        @dps_.P_hat.a[uci] = @dps_.P_hat_0.a[uci]
        @dps_.As.a[uci] = 0.0
        @dps_.hs.a[uci] = 0.0
        @dps_.hs_prev_iter.a[uci] = 0.0
      end
      @dps_.surcharged.a[uci] = (now_surcharged ? 1 : 0) & 0xFF
      ci += 1
    end
    self.spatialSmoothP(ctx)
  end

  def spatialSmoothP(ctx)
    links = ctx.links
    un = @n_nodes_ < 0 ? @n_nodes_ + 0x10000000000000000 : @n_nodes_
    if !$dynwave_DWSolver_S_node_P_sum_33_done
      $dynwave_DWSolver_S_node_P_sum_33 = NewVecD()
      $dynwave_DWSolver_S_node_P_sum_33_done = true
    end
    if !$dynwave_DWSolver_S_node_P_count_34_done
      $dynwave_DWSolver_S_node_P_count_34 = NewVecI()
      $dynwave_DWSolver_S_node_P_count_34_done = true
    end
    $dynwave_DWSolver_S_node_P_sum_33.assign_ul_T(un, 0.0)
    $dynwave_DWSolver_S_node_P_count_34.assign_ul_T(un, 0)
    ci = 0
    ci = 0
    _n1 = @n_conduits_
    while ci < _n1
      j = @conduit_idx_.a[ci]
      uj = j < 0 ? j + 0x10000000000000000 : j
      uci = ci
      if @is_open_.a[uj] != 0
        ci += 1
        next
      end
      n1 = links.node1.a[uj]
      n2 = links.node2.a[uj]
      if (n1 >= 0) && (n1 < @n_nodes_)
        $dynwave_DWSolver_S_node_P_sum_33.a[n1 < 0 ? n1 + 0x10000000000000000 : n1] += @dps_.P_hat.a[uci]
        Cpp::Cell.new(0).v = ($dynwave_DWSolver_S_node_P_count_34.a[n1 < 0 ? n1 + 0x10000000000000000 : n1] += 1) - 1
      end
      if (n2 >= 0) && (n2 < @n_nodes_)
        $dynwave_DWSolver_S_node_P_sum_33.a[n2 < 0 ? n2 + 0x10000000000000000 : n2] += @dps_.P_hat.a[uci]
        Cpp::Cell.new(0).v = ($dynwave_DWSolver_S_node_P_count_34.a[n2 < 0 ? n2 + 0x10000000000000000 : n2] += 1) - 1
      end
      ci += 1
    end
    ci_2 = 0
    ci_2 = 0
    _n2 = @n_conduits_
    while ci_2 < _n2
      j_2 = @conduit_idx_.a[ci_2]
      uj_2 = j_2 < 0 ? j_2 + 0x10000000000000000 : j_2
      uci_2 = ci_2
      if @is_open_.a[uj_2] != 0
        ci_2 += 1
        next
      end
      n1_2 = links.node1.a[uj_2]
      n2_2 = links.node2.a[uj_2]
      _P_face1 = @dps_.P_hat.a[uci_2]
      _P_face2 = @dps_.P_hat.a[uci_2]
      if ((n1_2 >= 0) && (n1_2 < @n_nodes_)) && ($dynwave_DWSolver_S_node_P_count_34.a[n1_2 < 0 ? n1_2 + 0x10000000000000000 : n1_2] > 0)
        _P_face1 = (_n4 = $dynwave_DWSolver_S_node_P_sum_33.a[n1_2 < 0 ? n1_2 + 0x10000000000000000 : n1_2]; (_d3 = $dynwave_DWSolver_S_node_P_count_34.a[n1_2 < 0 ? n1_2 + 0x10000000000000000 : n1_2]) != 0.0 ? _n4 / _d3 : fdiv0(_n4, _d3))
      end
      if ((n2_2 >= 0) && (n2_2 < @n_nodes_)) && ($dynwave_DWSolver_S_node_P_count_34.a[n2_2 < 0 ? n2_2 + 0x10000000000000000 : n2_2] > 0)
        _P_face2 = (_n6 = $dynwave_DWSolver_S_node_P_sum_33.a[n2_2 < 0 ? n2_2 + 0x10000000000000000 : n2_2]; (_d5 = $dynwave_DWSolver_S_node_P_count_34.a[n2_2 < 0 ? n2_2 + 0x10000000000000000 : n2_2]) != 0.0 ? _n6 / _d5 : fdiv0(_n6, _d5))
      end
      @dps_.P.a[uci_2] = 0.5 * (_P_face1 + _P_face2)
      @dps_.P.a[uci_2] = (_m7 = @dps_.P.a[uci_2]; _m7 < 1.0 ? 1.0 : _m7)
      ci_2 += 1
    end
  end

