  def Assign(s)
    if self.equal?(s)
      return
    end
    @head_tol = s.head_tol
    @max_trials = s.max_trials
    @omega = s.omega
    @surcharge_method = s.surcharge_method
    @node_continuity = s.node_continuity
    @anderson_accel = s.anderson_accel
    @unsteady_friction = s.unsteady_friction
    @uf_k3 = s.uf_k3
    @tpa_celerity = s.tpa_celerity
    @uf_nb_up_.Assign_VecT(s.uf_nb_up_)
    @uf_nb_dn_.Assign_VecT(s.uf_nb_dn_)
