    return !(@xnode_.sumdqdh.n == 0)
  end

  def nodeNewSurfAreaDataMut
    return @xnode_.new_surf_area.data()
  end

  def isBypassed(j)
    uj = j < 0 ? j + 0x10000000000000000 : j
    return (uj < @bypassed_.n) && (@bypassed_.a[uj] != 0)
  end

  def nodeSumDqdh(n)
    return Cpp::ArrRef.new(@xnode_.sumdqdh.a, n < 0 ? n + 0x10000000000000000 : n)
  end
