class Dynwave_DPSConfig
  include Cpp::ICopy
  attr_accessor :c_pT, :alpha, :r, :c_pT_sq

  def initialize
    @c_pT = 0.0
    @alpha = 0.0
    @r = 0.0
    @c_pT_sq = 0.0
  end

  def __init_rDPSConfig(p)
    @c_pT = p.c_pT
    @alpha = p.alpha
    @r = p.r
    @c_pT_sq = p.c_pT_sq
  end

  def __init_mDPSConfig(p)
    @c_pT = p.c_pT
    @alpha = p.alpha
    @r = p.r
    @c_pT_sq = p.c_pT_sq
  end

  def __init_d
    @c_pT = 25.0
    @alpha = 3.0
    @r = 0.5
    @c_pT_sq = 625.0
  end

  def ctor_dynwave_DPSConfig
    self.__init_d()
  end

  def Clone
    o = Dynwave_DPSConfig.new
    o.__CopyFrom_DPSConfig(self)
    return o
  end

  def __CopyFrom_DPSConfig(s)
    @c_pT = s.c_pT
    @alpha = s.alpha
    @r = s.r
    @c_pT_sq = s.c_pT_sq
  end

  def Assign(s)
    if self.equal?(s)
      return
    end
    @c_pT = s.c_pT
    @alpha = s.alpha
    @r = s.r
    @c_pT_sq = s.c_pT_sq
  end

  def MoveFrom(s)
    if self.equal?(s)
      return
    end
    @c_pT = s.c_pT
    @alpha = s.alpha
    @r = s.r
    @c_pT_sq = s.c_pT_sq
  end
end

