class Exfil_ExfilSolver
  include Cpp::ICopy
  attr_accessor :soa_

  def initialize
    @soa_ = nil
  end

  def init(ctx)
    nodes = ctx.nodes
    n_nodes = nodes.count()
    n_exfil = 0
    i = 0
    i = 0
    while i < n_nodes
      ui = i
      sr = ctx.node_subtypes.storage_row(i)
      ksat = (sr >= 0) ? F_lidnode_bottomConductivity(ctx, sr) : 0.0
      if (nodes.type.a[ui] == 3) && (ksat > 0.0)
        n_exfil += 1
      end
      i += 1
    end
    if n_exfil == 0
      @soa_.count = 0
      return
    end
    @soa_.resize(n_exfil)
    _BIG = 10000000000.0
    k = 0
    i_2 = 0
    i_2 = 0
    while i_2 < n_nodes
      ui_2 = i_2
      sr_2 = ctx.node_subtypes.storage_row(i_2)
      exf_suction = (sr_2 >= 0) ? ctx.node_subtypes.storages.exfil_suction.a[sr_2 < 0 ? sr_2 + 0x10000000000000000 : sr_2] : 0.0
      exf_ksat = (sr_2 >= 0) ? F_lidnode_bottomConductivity(ctx, sr_2) : 0.0
      exf_imd = (sr_2 >= 0) ? ctx.node_subtypes.storages.exfil_imd.a[sr_2 < 0 ? sr_2 + 0x10000000000000000 : sr_2] : 0.0
      if (nodes.type.a[ui_2] != 3) || (exf_ksat <= 0.0)
        i_2 += 1
        next
      end
      uk = k < 0 ? k + 0x10000000000000000 : k
      @soa_.node_idx.a[uk] = i_2
      F_infil_grnampt_init(@soa_.btm_ga.a[uk], exf_suction, exf_ksat, exf_imd, ctx.options)
      F_infil_grnampt_init(@soa_.bank_ga.a[uk], exf_suction, exf_ksat, exf_imd, ctx.options)
      curve_idx = (sr_2 >= 0) ? ctx.node_subtypes.storages.curve.a[sr_2 < 0 ? sr_2 + 0x10000000000000000 : sr_2] : (-1)
      if curve_idx >= 0
        curve = ctx.tables.op_Index__i(curve_idx)
        @soa_.btm_area.a[uk] = F_table_lookupEx(curve, 0.0)
        @soa_.bank_min_depth.a[uk] = 0.0
        @soa_.bank_max_depth.a[uk] = 0.0
        @soa_.bank_max_area.a[uk] = 0.0
        if !(curve.x.n == 0)
          alast = curve.y.a[0]
          ci = 1
          while ci < curve.x.n
            d = curve.x.a[ci]
            a = curve.y.a[ci]
            if a < alast
              break
            elsif a > alast
              @soa_.bank_max_area.a[uk] = a
              @soa_.bank_max_depth.a[uk] = d
            elsif @soa_.bank_max_area.a[uk] == 0.0
              @soa_.bank_min_depth.a[uk] = d
            else
              break
            end
            alast = a
            ci += 1
          end
        end
        ucf_len = F_ucf_UCF(3, ctx.options)
        @soa_.btm_area.a[uk] = (_n2 = @soa_.btm_area.a[uk]; (_d1 = ucf_len * ucf_len) != 0.0 ? _n2 / _d1 : fdiv0(_n2, _d1))
        @soa_.bank_max_area.a[uk] = (_n4 = @soa_.bank_max_area.a[uk]; (_d3 = ucf_len * ucf_len) != 0.0 ? _n4 / _d3 : fdiv0(_n4, _d3))
        @soa_.bank_min_depth.a[uk] = (_n6 = @soa_.bank_min_depth.a[uk]; (_d5 = ucf_len) != 0.0 ? _n6 / _d5 : fdiv0(_n6, _d5))
        @soa_.bank_max_depth.a[uk] = (_n8 = @soa_.bank_max_depth.a[uk]; (_d7 = ucf_len) != 0.0 ? _n8 / _d7 : fdiv0(_n8, _d7))
      else
        a_coeff = (sr_2 >= 0) ? ctx.node_subtypes.storages.a.a[sr_2 < 0 ? sr_2 + 0x10000000000000000 : sr_2] : 0.0
        b_coeff = (sr_2 >= 0) ? ctx.node_subtypes.storages.b.a[sr_2 < 0 ? sr_2 + 0x10000000000000000 : sr_2] : 0.0
        c_coeff = (sr_2 >= 0) ? ctx.node_subtypes.storages.c.a[sr_2 < 0 ? sr_2 + 0x10000000000000000 : sr_2] : 0.0
        sshape = (sr_2 >= 0) ? ctx.node_subtypes.storages.shape.a[sr_2 < 0 ? sr_2 + 0x10000000000000000 : sr_2] : 1
        btm = c_coeff
        if F_storage_shape_is_geometric(sshape)
        elsif b_coeff == 0.0
          btm += a_coeff
        end
        @soa_.btm_area.a[uk] = btm
        @soa_.bank_min_depth.a[uk] = 0.0
        @soa_.bank_max_depth.a[uk] = _BIG
        @soa_.bank_max_area.a[uk] = _BIG
      end
      k += 1
      i_2 += 1
    end
  end

  def computeAll(ctx, dt)
    nodes = ctx.nodes
    k = 0
    while k < @soa_.count
      uk = k < 0 ? k + 0x10000000000000000 : k
      ni = @soa_.node_idx.a[uk]
      if ni < 0
        k += 1
        next
      end
      uni = ni < 0 ? ni + 0x10000000000000000 : ni
      if F_lidnode_richardsMode(ctx, ni) || (F_lidnode_bottomMode(ctx, ni) != 0)
        ctx.node_subtypes.storages.exfil_rate.a[(_u1 = ctx.node_subtypes.storage_row(ni)) < 0 ? _u1 + 0x10000000000000000 : _u1] = 0.0
        k += 1
        next
      end
      if (uni < nodes.aquifer2d_bed.n) && (nodes.aquifer2d_bed.a[uni] != 0)
        sr0 = ctx.node_subtypes.storage_row(ni)
        if sr0 >= 0
          ctx.node_subtypes.storages.exfil_rate.a[sr0 < 0 ? sr0 + 0x10000000000000000 : sr0] = 0.0
        end
        k += 1
        next
      end
      depth = nodes.depth.a[uni]
      total_loss = 0.0
      infil_factor = ctx.climate_state.infil_factor
      recovery_factor = ctx.climate_state.recovery_factor
      _lam2 = ->(infil_factor, recovery_factor) do
        ->(ga, d) do
          if ga.IMDmax == 0.0
            return ga.Ks * infil_factor
          end
          return F_infil_grnampt_getInfil(ga, 0.0, d, dt, 3, infil_factor, recovery_factor)
        end
      end.(infil_factor, recovery_factor)
      ga_rate = _lam2
      total_loss += (ga_rate.call(@soa_.btm_ga.a[uk], depth) * @soa_.btm_area.a[uk]) * F_lidnode_bottomCloggingFactor(ctx, ctx.node_subtypes.storage_row(ni))
      if depth > @soa_.bank_min_depth.a[uk]
        area = F_node_getSurfArea(ctx.nodes, @soa_.node_idx.a[uk], depth, ctx.tables, F_ucf_getUnitSystem(ctx.options.flow_units), ctx.node_subtypes)
        area = (_m3 = @soa_.bank_max_area.a[uk]; _m3 < area ? _m3 : area) - @soa_.btm_area.a[uk]
        if area > 0.0
          bank_depth = depth
          if @soa_.bank_ga.a[uk].IMDmax != 0.0
            if depth > @soa_.bank_max_depth.a[uk]
              bank_depth = (depth - @soa_.bank_max_depth.a[uk]) + ((@soa_.bank_max_depth.a[uk] - @soa_.bank_min_depth.a[uk]) / 2.0)
            else
              bank_depth = (depth - @soa_.bank_min_depth.a[uk]) / 2.0
            end
          end
          total_loss += area * ga_rate.call(@soa_.bank_ga.a[uk], bank_depth)
        end
      end
      sr = ctx.node_subtypes.storage_row((uni + 0x80000000 & 0xFFFFFFFF) - 0x80000000)
      if sr >= 0
        ctx.node_subtypes.storages.exfil_rate.a[sr < 0 ? sr + 0x10000000000000000 : sr] = total_loss
      end
      k += 1
    end
  end

  def __init_d
    @soa_ = exfil_ExfilSoA__new()
  end

  def __init_rExfilSolver(p)
    self.__CopyFrom_ExfilSolver(p)
  end

  def __init_mExfilSolver(p)
    self.MoveFrom(p)
  end

  def ctor_exfil_ExfilSolver
    self.__init_d()
  end

  def Clone
    o = Exfil_ExfilSolver.new
    o.__CopyFrom_ExfilSolver(self)
    return o
  end

  def __CopyFrom_ExfilSolver(s)
    @soa_ = s.soa_.nil? ? nil : s.soa_.Clone()
  end

  def Assign(s)
    if self.equal?(s)
      return
    end
    @soa_.Assign(s.soa_)
  end

  def MoveFrom(s)
    if self.equal?(s)
      return
    end
    @soa_ = s.soa_
    s.soa_ = exfil_ExfilSoA__new()
  end

  def state__v
    return @soa_
  end
end

