class Hydstruct_StructureSolver
  include Cpp::ICopy
  attr_accessor :pumps_, :orifices_, :weirs_, :outlets_, :nc_indices_, :nc_group_k_

  def initialize
    @pumps_ = nil
    @orifices_ = nil
    @weirs_ = nil
    @outlets_ = nil
    @nc_indices_ = nil
    @nc_group_k_ = nil
  end

  def init(ctx)
    n_pumps = 0
    n_orifices = 0
    n_weirs = 0
    n_outlets = 0
    j = 0
    while j < ctx.n_links()
      uj = j < 0 ? j + 0x10000000000000000 : j
      case ctx.links.type.a[uj]
      when 1
        n_pumps += 1
      when 2
        n_orifices += 1
      when 3
        n_weirs += 1
      when 4
        n_outlets += 1
      else
      end
      j += 1
    end
    @pumps_.resize(n_pumps)
    @orifices_.resize(n_orifices)
    @weirs_.resize(n_weirs)
    @outlets_.resize(n_outlets)
    ip = 0
    io = 0
    iw = 0
    ix = 0
    j_2 = 0
    while j_2 < ctx.n_links()
      uj_2 = j_2 < 0 ? j_2 + 0x10000000000000000 : j_2
      case ctx.links.type.a[uj_2]
      when 1
        uk = ip < 0 ? ip + 0x10000000000000000 : ip
        _P = ctx.link_subtypes.pumps
        pr = (_u1 = ctx.link_subtypes.pump_row(j_2)) < 0 ? _u1 + 0x10000000000000000 : _u1
        @pumps_.link_idx.a[uk] = j_2
        @pumps_.curve_idx.a[uk] = _P.curve.a[pr]
        @pumps_.speed.a[uk] = ctx.links.setting.a[uj_2]
        @pumps_.y_on.a[uk] = _P.startup.a[pr]
        @pumps_.y_off.a[uk] = _P.shutoff.a[pr]
        ci = _P.curve.a[pr]
        if (ci >= 0) && (ci < ((ctx.tables.tables.n + 0x80000000 & 0xFFFFFFFF) - 0x80000000))
          tt = ctx.tables.tables.a[ci < 0 ? ci + 0x10000000000000000 : ci].type
          if (tt >= 7) && (tt <= 11)
            @pumps_.curve_type.a[uk] = ((tt - 6) + 0x80000000 & 0xFFFFFFFF) - 0x80000000
          else
            @pumps_.curve_type.a[uk] = 6
          end
        else
          @pumps_.curve_type.a[uk] = 6
        end
        ctx.link_subtypes.pumps.curve_type.a[pr] = @pumps_.curve_type.a[uk]
        ip += 1
      when 2
        uk_2 = io < 0 ? io + 0x10000000000000000 : io
        @orifices_.link_idx.a[uk_2] = j_2
        y_full = ctx.links.xsect_y_full.a[uj_2]
        route_step = ctx.options.linkValidateRoutingStep()
        _L = (2.0 * route_step) * ((_q2 = $F_constants_GRAVITY * y_full) > 0.0 ? Math.sqrt(_q2) : Math_Sqrt_d(_q2))
        @orifices_.length_eff.a[uk_2] = 200.0 < _L ? _L : 200.0
        io += 1
      when 3
        uk_3 = iw < 0 ? iw + 0x10000000000000000 : iw
        _W = ctx.link_subtypes.weirs
        wr = (_u3 = ctx.link_subtypes.weir_row(j_2)) < 0 ? _u3 + 0x10000000000000000 : _u3
        @weirs_.link_idx.a[uk_3] = j_2
        @weirs_.c_disch1.a[uk_3] = _W.cd.a[wr]
        @weirs_.c_disch2.a[uk_3] = _W.cd2.a[wr]
        @weirs_.can_surcharge.a[uk_3] = _W.can_surcharge.a[wr]
