class Inlet_InletSolver
  include Cpp::ICopy
  attr_accessor :soa_, :node_inlet_flow_, :node_inflow_, :nsides_prev_, :is_capture_node_

  def initialize
    @soa_ = nil
    @node_inlet_flow_ = nil
    @node_inflow_ = nil
    @nsides_prev_ = 0
    @is_capture_node_ = nil
  end

  def init(ctx)
    usages = ctx.inlet_usages
    n = usages.count()
    @soa_.resize(n)
    if n == 0
      return
    end
    nn = ctx.n_nodes()
    nl = ctx.n_links()
    @node_inlet_flow_.assign_ul_T(nn < 0 ? nn + 0x10000000000000000 : nn, 0.0)
    @node_inflow_.assign_ul_T(nn < 0 ? nn + 0x10000000000000000 : nn, 0.0)
    @is_capture_node_.assign_ul_T(nn < 0 ? nn + 0x10000000000000000 : nn, 0)
    us = F_ucf_getUnitSystem(ctx.options.flow_units)
    inv_len = $F_ucf_Ucf_inv[3][us < 0 ? us + 0x10000000000000000 : us]
    inv_flow = $F_ucf_Qcf_inv[(_u1 = ctx.options.flow_units) < 0 ? _u1 + 0x10000000000000000 : _u1]
    out_degree = NewVecI_ul_T(nn < 0 ? nn + 0x10000000000000000 : nn, 0)
    j = 0
    j = 0
    while j < nl
      uj = j
      m = ((ctx.links.direction.a[uj] < 0) ? Cpp::ArrRef.new(ctx.links.node2.a, uj) : Cpp::ArrRef.new(ctx.links.node1.a, uj)).v
      if (m < 0) || (m >= nn)
        j += 1
        next
      end
      if ctx.nodes.type.a[m < 0 ? m + 0x10000000000000000 : m] == 1
        m = ((ctx.links.direction.a[uj] < 0) ? Cpp::ArrRef.new(ctx.links.node1.a, uj) : Cpp::ArrRef.new(ctx.links.node2.a, uj)).v
        if (m < 0) || (m >= nn)
          j += 1
          next
        end
      end
      Cpp::Cell.new(0).v = (out_degree.a[m < 0 ? m + 0x10000000000000000 : m] += 1) - 1
      j += 1
    end
    i = 0
    i = 0
    while i < n
      ui = i
      li = usages.link_index.a[ui]
      nh = usages.node_host.a[ui]
      di = usages.design_index.a[ui]
      @soa_.link_idx.a[ui] = li
      @soa_.host_node.a[ui] = nh
      @soa_.node_idx.a[ui] = usages.node_index.a[ui]
      if (@soa_.node_idx.a[ui] >= 0) && (@soa_.node_idx.a[ui] < nn)
        @is_capture_node_.a[(_u2 = @soa_.node_idx.a[ui]) < 0 ? _u2 + 0x10000000000000000 : _u2] = 1
      end
      @soa_.num_inlets.a[ui] = usages.num_inlets.a[ui]
      @soa_.clog_factor.a[ui] = usages.clog_factor.a[ui]
      @soa_.flow_limit.a[ui] = usages.flow_limit.a[ui] * inv_flow
      @soa_.local_depress.a[ui] = usages.local_depress.a[ui] * inv_len
      @soa_.local_width.a[ui] = usages.local_width.a[ui] * inv_len
      @soa_.placement.a[ui] = usages.placement.a[ui]
      if (di >= 0) && (di < ctx.inlets.count())
        ud = di < 0 ? di + 0x10000000000000000 : di
        type_str = ctx.inlets.inlet_type.a[ud]
        itype = 6
        if type_str.EqLit(R_Lit("GRATE"))
          itype = 0
        elsif type_str.EqLit(R_Lit("CURB"))
          itype = 1
        elsif type_str.EqLit(R_Lit("COMBO"))
          itype = 2
        elsif type_str.EqLit(R_Lit("SLOTTED"))
          itype = 3
        elsif type_str.EqLit(R_Lit("DROP_GRATE"))
          itype = 4
        elsif type_str.EqLit(R_Lit("DROP_CURB"))
          itype = 5
        elsif type_str.EqLit(R_Lit("CUSTOM"))
          itype = 6
        end
        @soa_.inlet_type.a[ui] = itype
        gt_str = ctx.inlets.grate_type.a[ud]
        gt = 7
        if gt_str.EqLit(R_Lit("P_BAR-50"))
          gt = 0
        elsif gt_str.EqLit(R_Lit("P_BAR-50x100"))
          gt = 1
        elsif gt_str.EqLit(R_Lit("P_BAR-30"))
          gt = 2
        elsif gt_str.EqLit(R_Lit("CURVED_VANE"))
          gt = 3
        elsif gt_str.EqLit(R_Lit("TILT_BAR-45"))
          gt = 4
        elsif gt_str.EqLit(R_Lit("TILT_BAR-30"))
          gt = 5
        elsif gt_str.EqLit(R_Lit("RETICULINE"))
          gt = 6
        end
        @soa_.grate_type.a[ui] = gt
        if itype == 3
          @soa_.slotted_length.a[ui] = ctx.inlets.length.a[ud] * inv_len
          @soa_.slotted_width.a[ui] = ctx.inlets.width.a[ud] * inv_len
        elsif ((itype == 0) || (itype == 4)) || (itype == 2)
          @soa_.grate_length.a[ui] = ctx.inlets.length.a[ud] * inv_len
          @soa_.grate_width.a[ui] = ctx.inlets.width.a[ud] * inv_len
        end
        @soa_.open_area.a[ui] = ctx.inlets.open_area.a[ud]
        @soa_.splash_veloc.a[ui] = ctx.inlets.splash_veloc.a[ud] * inv_len
        if ((itype == 1) || (itype == 5)) || (itype == 2)
          @soa_.curb_length.a[ui] = ctx.inlets.curb_length.a[ud] * inv_len
          @soa_.curb_height.a[ui] = ctx.inlets.curb_height.a[ud] * inv_len
          @soa_.curb_throat.a[ui] = ctx.inlets.curb_throat.a[ud]
        end
        @soa_.curve_index.a[ui] = ctx.inlets.curve_index.a[ud]
        @soa_.curve_kind.a[ui] = ctx.inlets.curve_kind.a[ud]
      end
      bypass = -1
      up = Cpp::Cell.new(-1)
      up2 = Cpp::Cell.new(-1)
      if (nh >= 0) && (nh < nn)
        bypass = nh
        j_2 = 0
        while (j_2 < nl) && (up2.v < 0)
          uj_2 = j_2 < 0 ? j_2 + 0x10000000000000000 : j_2
          if ctx.links.type.a[uj_2] != 0
            j_2 += 1
            next
          end
          if ctx.links.node2.a[uj_2] != nh
            j_2 += 1
            next
          end
          if up.v < 0
            up.v = j_2
          else
            up2.v = j_2
          end
          j_2 += 1
        end
        if up.v < 0
          j_3 = 0
          j_3 = 0
          while j_3 < nl
            uj_3 = j_3
            if (ctx.links.type.a[uj_3] == 0) && (ctx.links.node1.a[uj_3] == nh)
              up.v = j_3
              break
            end
            j_3 += 1
          end
        end
        if up2.v >= 0
          @soa_.two_inbound.a[ui] = 1
          ca = ctx.link_subtypes.conduit_row(up.v)
          cb = ctx.link_subtypes.conduit_row(up2.v)
          sa = (ca >= 0) ? ctx.link_subtypes.conduits.slope.a[ca < 0 ? ca + 0x10000000000000000 : ca] : 0.0
          sb = (cb >= 0) ? ctx.link_subtypes.conduits.slope.a[cb < 0 ? cb + 0x10000000000000000 : cb] : 0.0
          if sb > sa
            Std_swap__I(up, up2)
          end
        end
      elsif (li >= 0) && (li < nl)
        bypass = ctx.links.node2.a[li < 0 ? li + 0x10000000000000000 : li]
        up.v = li
      end
      @soa_.bypass_node.a[ui] = bypass
      @soa_.up_link.a[ui] = up.v
      @soa_.up_link2.a[ui] = up2.v
      si = usages.street_index.a[ui]
      if (si >= 0) && (si < ctx.streets.count())
        su = si < 0 ? si + 0x10000000000000000 : si
        @soa_.sx.a[ui] = ctx.streets.sx.a[su] / 100.0
        @soa_.gutter_depression.a[ui] = ctx.streets.gutter_depres.a[su] * inv_len
        @soa_.gutter_width.a[ui] = ctx.streets.gutter_width.a[su] * inv_len
        @soa_.road_roughness.a[ui] = ctx.streets.n_road.a[su]
        @soa_.n_sides.a[ui] = ctx.streets.sides.a[su]
        @soa_.t_crown.a[ui] = ctx.streets.t_crown.a[su] * inv_len
