  end

  def __init_rAcceptedWaterVolumes(p)
    @face_forward = p.face_forward.Clone()
    @face_reverse = p.face_reverse.Clone()
    @structure_forward = p.structure_forward.Clone()
    @structure_reverse = p.structure_reverse.Clone()
    @cell_lateral = p.cell_lateral.Clone()
    @cell_loss = p.cell_loss.Clone()
    @node_deficit = p.node_deficit.Clone()
    @face_lateral_left = p.face_lateral_left.Clone()
    @face_lateral_right = p.face_lateral_right.Clone()
    @face_spill = p.face_spill.Clone()
  end

  def __init_mAcceptedWaterVolumes(p)
    self.MoveFrom(p)
  end

  def __init_d
    @face_forward = NewVecD()
    @face_reverse = NewVecD()
    @structure_forward = NewVecD()
    @structure_reverse = NewVecD()
    @cell_lateral = NewVecD()
    @cell_loss = NewVecD()
    @node_deficit = NewVecD()
    @face_lateral_left = NewVecD()
    @face_lateral_right = NewVecD()
    @face_spill = NewVecD()
  end

  def ctor_fv_AcceptedWaterVolumes
    self.__init_d()
  end

  def Clone
    o = Fv_AcceptedWaterVolumes.new
    o.__CopyFrom_AcceptedWaterVolumes(self)
    return o
  end

  def __CopyFrom_AcceptedWaterVolumes(s)
    @face_forward = s.face_forward.nil? ? nil : s.face_forward.Clone()
    @face_reverse = s.face_reverse.nil? ? nil : s.face_reverse.Clone()
    @structure_forward = s.structure_forward.nil? ? nil : s.structure_forward.Clone()
    @structure_reverse = s.structure_reverse.nil? ? nil : s.structure_reverse.Clone()
    @cell_lateral = s.cell_lateral.nil? ? nil : s.cell_lateral.Clone()
    @cell_loss = s.cell_loss.nil? ? nil : s.cell_loss.Clone()
    @node_deficit = s.node_deficit.nil? ? nil : s.node_deficit.Clone()
    @face_lateral_left = s.face_lateral_left.nil? ? nil : s.face_lateral_left.Clone()
    @face_lateral_right = s.face_lateral_right.nil? ? nil : s.face_lateral_right.Clone()
    @face_spill = s.face_spill.nil? ? nil : s.face_spill.Clone()
  end

  def Assign(s)
    if self.equal?(s)
      return
    end
    @face_forward.Assign_VecT(s.face_forward)
    @face_reverse.Assign_VecT(s.face_reverse)
    @structure_forward.Assign_VecT(s.structure_forward)
    @structure_reverse.Assign_VecT(s.structure_reverse)
    @cell_lateral.Assign_VecT(s.cell_lateral)
    @cell_loss.Assign_VecT(s.cell_loss)
    @node_deficit.Assign_VecT(s.node_deficit)
    @face_lateral_left.Assign_VecT(s.face_lateral_left)
    @face_lateral_right.Assign_VecT(s.face_lateral_right)
    @face_spill.Assign_VecT(s.face_spill)
  end

  def MoveFrom(s)
    if self.equal?(s)
      return
    end
    @face_forward = s.face_forward
    s.face_forward = NewVecD()
    @face_reverse = s.face_reverse
    s.face_reverse = NewVecD()
    @structure_forward = s.structure_forward
    s.structure_forward = NewVecD()
    @structure_reverse = s.structure_reverse
    s.structure_reverse = NewVecD()
    @cell_lateral = s.cell_lateral
    s.cell_lateral = NewVecD()
    @cell_loss = s.cell_loss
    s.cell_loss = NewVecD()
    @node_deficit = s.node_deficit
    s.node_deficit = NewVecD()
    @face_lateral_left = s.face_lateral_left
    s.face_lateral_left = NewVecD()
    @face_lateral_right = s.face_lateral_right
    s.face_lateral_right = NewVecD()
    @face_spill = s.face_spill
    s.face_spill = NewVecD()
  end

  def resize(nf, ns, nc, nn)
    @face_forward.assign_ul_T(nf, 0.0)
    @face_reverse.assign_ul_T(nf, 0.0)
    @structure_forward.assign_ul_T(ns, 0.0)
    @structure_reverse.assign_ul_T(ns, 0.0)
    @cell_lateral.assign_ul_T(nc, 0.0)
    @cell_loss.assign_ul_T(nc, 0.0)
    @node_deficit.assign_ul_T(nn, 0.0)
    @face_lateral_left.assign_ul_T(nf, 0.0)
    @face_lateral_right.assign_ul_T(nf, 0.0)
    @face_spill.assign_ul_T(nf, 0.0)
  end

  def each(fn)
    fn.call(@face_forward)
    fn.call(@face_reverse)
    fn.call(@structure_forward)
    fn.call(@structure_reverse)
    fn.call(@cell_lateral)
    fn.call(@cell_loss)
    fn.call(@node_deficit)
    fn.call(@face_lateral_left)
    fn.call(@face_lateral_right)
    fn.call(@face_spill)
  end

  def clear
    self.each(->(v) { Algo_fill_IterT_IterT_T__D(v.begin(), v.end(), 0.0); nil })
  end

  def averageDelta(base)
    _lam1 = ->(v, b) do
      i = 0
      while i < v.n
        v.a[i] = b.a[i] + (0.5 * (v.a[i] - b.a[i]))
        i += 1
      end
      return
      nil
    end
    avg = _lam1
    avg.call(@face_forward, base.face_forward)
    avg.call(@face_reverse, base.face_reverse)
    avg.call(@structure_forward, base.structure_forward)
    avg.call(@structure_reverse, base.structure_reverse)
    avg.call(@cell_lateral, base.cell_lateral)
    avg.call(@cell_loss, base.cell_loss)
    avg.call(@node_deficit, base.node_deficit)
    avg.call(@face_lateral_left, base.face_lateral_left)
    avg.call(@face_lateral_right, base.face_lateral_right)
    avg.call(@face_spill, base.face_spill)
  end

  def face(f, volume)
    if volume >= 0.0
      @face_forward.a[f] += volume
    else
      @face_reverse.a[f] -= volume
    end
  end

  def structure(s, volume)
    if volume >= 0.0
      @structure_forward.a[s] += volume
    else
      @structure_reverse.a[s] -= volume
    end
  end
end

