  def advance(t_current, t_target, forcing)
    if ((!@pressure_candidate_) || (!(!@mesh_.nil?))) || (t_target <= t_current)
      return self.advanceImpl(t_current, t_target, forcing)
    end
    self.validatePressureCandidate(forcing)
    @pressure_rejections_ = 0
    state = @state_.Clone()
    water = @water_.Clone()
    unmet = @unmet_withdrawal_.Clone()
    carry = @node_carry_.Clone()
    exchange = @node_exch_.Clone()
    incoming = @node_in_.Clone()
    outgoing = @node_out_.Clone()
    flood = @flood_vol_.Clone()
    qint = @cell_q_int_.Clone()
    dummy = @dummy_vol_.Clone()
    inlet = @inlet_control_.Clone()
    published = @node_pub_.Clone()
    last = @last_h_
    minimum = @min_h_
    cached = @dt_cache_
    simulated = @sim_time_
    suggested = @suggested_h_
    total = @total_steps_
    previous_steps = @last_nsteps_
    begin
      reached = self.advanceImpl(t_current, t_target, forcing)
      if reached != t_target
        raise NewRuntimeError_Str(Str_from_CPtr(R_Lit("Nonlinear pressure-storage candidate did not finish its routing window.")))
      end
      return reached
    rescue StandardError => __ex1
      Dbg_Caught(__ex1)
      @state_.Assign(state)
      @water_.Assign(water)
      @unmet_withdrawal_.Assign_VecT(unmet)
      @node_carry_.Assign_VecT(carry)
      @node_exch_.Assign_VecT(exchange)
      @node_in_.Assign_VecT(incoming)
      @node_out_.Assign_VecT(outgoing)
      @flood_vol_.Assign_VecT(flood)
      @cell_q_int_.Assign_VecT(qint)
      @dummy_vol_.Assign_VecT(dummy)
      @inlet_control_.Assign_VecT(inlet)
      @node_pub_.Assign_VecT(published)
      @last_h_ = last
      @min_h_ = minimum
      @dt_cache_ = cached
      @sim_time_ = simulated
      @suggested_h_ = suggested
      @total_steps_ = total
      @last_nsteps_ = previous_steps
      Algo_fill_IterT_IterT_T__D(@face_lat_spill_.begin(), @face_lat_spill_.end(), 0.0)
      self.refreshDepths()
      @state_.Assign(state)
      @state_clean_ = false
      @lists_valid_ = false
      @census_count_ = 0
      raise
    end
  end

  def run_stats
    s = fv_INetworkSolver_RunStats__new()
    s.nsteps = @total_steps_
    s.nflux = @total_flux_
    s.last_h = @last_h_
    s.min_h = @min_h_
    s.avg_h = (@total_steps_ > 0) ? (@total_steps_.to_f != 0.0 ? @sim_time_ / @total_steps_.to_f : fdiv0(@sim_time_, @total_steps_.to_f)) : 0.0
    if @active_n_ > 0
      s.active_frac_mean = @active_n_.to_f != 0.0 ? @active_sum_ / @active_n_.to_f : fdiv0(@active_sum_, @active_n_.to_f)
      s.active_frac_min = @active_min_
      s.active_frac_max = @active_max_
    end
    s.n_tiers = $F_fv_kMaxLtsTiers < @lts_tiers_ ? $F_fv_kMaxLtsTiers : @lts_tiers_
    k = 0
    k = 0
    _n1 = s.n_tiers
    while k < _n1
      s.tier_cells[k] = @tier_occupancy_[k]
      k += 1
    end
    s.dt_argmin_pressurized = @dt_argmin_pressurized_
    s.dt_argmin_band = @dt_argmin_band_
    s.dt_argmin_free = @dt_argmin_free_
    s.dt_argmin_node = @dt_argmin_node_
    s.n_macro_cycles = @n_macro_cycles_
    s.n_macro_rejected = @n_macro_rejected_
    return fv_INetworkSolver_RunStats_MoveNew(s)
  end

  def nodeVolumeFromDepth(node, depth)
    un = node < 0 ? node + 0x10000000000000000 : node
    if depth <= 0.0
      return 0.0
    end
    full = @mesh_.node_full_depth.a[un]
    if ((@mesh_.node_can_pond.a[un] != 0) && (full > 0.0)) && (depth > full)
      return self.nodeVolumeFromDepth(node, full) + ((depth - full) * @mesh_.node_ponded_area.a[un])
    end
    off = @mesh_.node_vol_off.a[un]
    if off < 0
      return @state_.node_surf_area.a[un] * depth
    end
    dmax = @mesh_.node_vol_dmax.a[un]
    n = $F_fv_kNodeVolSamples
    vmax = @mesh_.node_vol_tbl.a[(_u1 = (((off + n) - 1) + 0x80000000 & 0xFFFFFFFF) - 0x80000000) < 0 ? _u1 + 0x10000000000000000 : _u1]
    if depth >= dmax
      return vmax + (@mesh_.node_vol_atop.a[un] * (depth - dmax))
    end
    dd = (_d2 = ((n - 1) + 0x80000000 & 0xFFFFFFFF) - 0x80000000) != 0.0 ? dmax / _d2 : fdiv0(dmax, _d2)
    i = Conv_D2I(dd != 0.0 ? depth / dd : fdiv0(depth, dd))
    if i > (((n - 2) + 0x80000000 & 0xFFFFFFFF) - 0x80000000)
      i = ((n - 2) + 0x80000000 & 0xFFFFFFFF) - 0x80000000
    end
    if i < 0
      i = 0
    end
    t = (_n4 = depth - (i * dd); (_d3 = dd) != 0.0 ? _n4 / _d3 : fdiv0(_n4, _d3))
    v0 = @mesh_.node_vol_tbl.a[(_u5 = ((off + i) + 0x80000000 & 0xFFFFFFFF) - 0x80000000) < 0 ? _u5 + 0x10000000000000000 : _u5]
    v1 = @mesh_.node_vol_tbl.a[(_u6 = (((off + i) + 1) + 0x80000000 & 0xFFFFFFFF) - 0x80000000) < 0 ? _u6 + 0x10000000000000000 : _u6]
    return v0 + ((v1 - v0) * t)
  end

  def advanceImpl(t_current, t_target, forcing)
    if (!(!@mesh_.nil?)) || (t_target <= t_current)
      return t_target
    end
    @forcing_ = forcing
    Algo_fill_IterT_IterT_T__D(@unmet_withdrawal_.begin(), @unmet_withdrawal_.end(), 0.0)
    if @water_tracking_
      @water_.clear()
    end
    Algo_fill_IterT_IterT_T__D(@node_exch_.begin(), @node_exch_.end(), 0.0)
    Algo_fill_IterT_IterT_T__D(@node_in_.begin(), @node_in_.end(), 0.0)
    Algo_fill_IterT_IterT_T__D(@node_out_.begin(), @node_out_.end(), 0.0)
    Algo_fill_IterT_IterT_T__D(@flood_vol_.begin(), @flood_vol_.end(), 0.0)
