  def last_num_steps
    return @last_nsteps_
  end

  def suggested_step
    return @suggested_h_
  end

  def divergence(d)
    if @div_link_ < 0
      return false
    end
    d.link = @div_link_
    d.value = @div_value_
    d.what = @div_what_
    return true
  end

  def setConduitStepSink(fn, user)
    @step_sink_ = fn
    @step_sink_user_ = user
  end

  def trackAcceptedWater(enabled)
    @water_tracking_ = enabled
    if enabled && (!@mesh_.nil?)
      @water_.resize((_u1 = @mesh_.n_faces()) < 0 ? _u1 + 0x10000000000000000 : _u1, @mesh_.struct_link.n, (_u2 = @mesh_.n_cells()) < 0 ? _u2 + 0x10000000000000000 : _u2, (_u3 = @mesh_.n_nodes()) < 0 ? _u3 + 0x10000000000000000 : _u3)
    else
      _o4 = fv_AcceptedWaterVolumes__new()
      _o4.face_forward = NewVecD()
      _o4.face_reverse = NewVecD()
      _o4.structure_forward = NewVecD()
      _o4.structure_reverse = NewVecD()
      _o4.cell_lateral = NewVecD()
      _o4.cell_loss = NewVecD()
      _o4.node_deficit = NewVecD()
      _o4.face_lateral_left = NewVecD()
      _o4.face_lateral_right = NewVecD()
      _o4.face_spill = NewVecD()
      @water_.MoveFrom(_o4)
    end
    @save_water_.Assign(@water_)
    @rk_water_.Assign(@water_)
  end

  def acceptedWater
    return @water_
  end

  def requireConservativeNodeBalance(enabled)
    @conservative_node_balance_ = enabled
  end

  def withdrawalRates__v
    return @withdrawal_rates_
  end

  def withdrawalRates__v_t2
    return @withdrawal_rates_
  end

  def unmetWithdrawalVolumes
    return @unmet_withdrawal_
  end

  def node_continuity_carry
    return @node_carry_
  end

  def node_inflow_volume
    return @node_in_
  end

  def node_outflow_volume
    return @node_out_
  end

  def bookDivertedLateral(un, dt, forcing)
    if ((@node_lat_div_.n == 0) || (!(@node_lat_div_.a[un] != 0))) || (!(!forcing.node_lateral.get_IsNull()))
      return
    end
    lat = forcing.node_lateral.get_Item_ul(un)
    if lat > 0.0
      @node_out_.a[un] += lat * dt
    end
  end

  def inlet_control
    return @inlet_control_
  end

  def node_flood_volume
    return @flood_vol_
  end

  def dummy_volume
    return @dummy_vol_
  end

  def node_publish_stage
    return @node_pub_
  end

  def cell_flow_integral
    return @cell_q_int_
  end

  def nodeLateral(forcing, un)
    if (!(@node_lat_div_.n == 0)) && (@node_lat_div_.a[un] != 0)
      return 0.0
    end
    return (!forcing.node_lateral.get_IsNull()) ? forcing.node_lateral.get_Item_ul(un) : 0.0
  end

  def algebraicActive(n)
    un = n < 0 ? n + 0x10000000000000000 : n
    if !(@node_alg_.a[un] != 0)
      return false
    end
    if (@mesh_.node_can_pond.a[un] != 0) && (@state_.node_volume.a[un] > @node_vfull_.a[un])
      return false
    end
    return true
  end

  def incidentPressurized(un)
    p = @mesh_.node_face_ptr.a[un]
    while p < @mesh_.node_face_ptr.a[(un + 1) & 0xFFFFFFFFFFFFFFFF]
      uf = (_u1 = @mesh_.node_face_idx.a[p < 0 ? p + 0x10000000000000000 : p]) < 0 ? _u1 + 0x10000000000000000 : _u1
      c = ((@mesh_.face_cl.a[uf] >= 0) ? Cpp::ArrRef.new(@mesh_.face_cl.a, uf) : Cpp::ArrRef.new(@mesh_.face_cr.a, uf)).v
      if c < 0
        p += 1
        next
      end
      uc = c < 0 ? c + 0x10000000000000000 : c
      if self.tpaCell(uc)
        return true
      end
      g = @mesh_.geom.a[(_u2 = @mesh_.cell_geom.a[uc]) < 0 ? _u2 + 0x10000000000000000 : _u2]
      if (!(g.is_open != 0)) && (@state_.cell_h.a[uc] >= g.y_crown)
        return true
      end
      p += 1
    end
    return false
  end

  def nodeQDummy(un)
    return (@node_qdummy_.n == 0) ? 0.0 : @node_qdummy_.a[un]
  end

  def ltsEligible
    return ((@opts_.lts && (@opts_.time_integration != 1)) && (!@state_.nil?)) && (@state_.n_species == 0)
  end

  def faceIsLive(f)
    return @all_faces_live_ || ((!(@live_stamp_.n == 0)) && (@live_stamp_.a[f < 0 ? f + 0x10000000000000000 : f] == @live_gen_))
  end

  def tpaCell(uc)
    return @tpa_ && (@state_.cell_tpa.a[uc] != 0)
  end
end

