  include Cpp::ICopy
  attr_accessor :y_full, :dh, :inv_dh, :a_crown, :t_slot, :i1_crown, :r_full, :inv_a_crown_n, :c2, :c1, :p0, :p1, :kind, :A, :M, :I1, :R, :j_of_a

  def initialize
    @y_full = 0.0
    @dh = 0.0
    @inv_dh = 0.0
    @a_crown = 0.0
    @t_slot = 0.0
    @i1_crown = 0.0
    @r_full = 0.0
    @inv_a_crown_n = 0.0
    @c2 = 0.0
    @c1 = 0.0
    @p0 = 0.0
    @p1 = 0.0
    @kind = 0
    @A = nil
    @M = nil
    @I1 = nil
    @R = nil
    @j_of_a = nil
  end

  def __init_rFvClosure(p)
    @y_full = p.y_full
    @dh = p.dh
    @inv_dh = p.inv_dh
    @a_crown = p.a_crown
