class Lid_LIDSolver
  include Cpp::ICopy
  include Cpp::IDisposable
  attr_accessor :groups_, :usage_order_, :old_runoff_sec_, :rpt_files_, :recovery_factor_, :native_infil_, :max_native_infil_, :infil_factor_

  def initialize
    @groups_ = nil
    @usage_order_ = nil
    @old_runoff_sec_ = 0.0
    @rpt_files_ = nil
    @recovery_factor_ = 0.0
    @native_infil_ = nil
    @max_native_infil_ = nil
    @infil_factor_ = nil
  end

  def init(ctx)
    @groups_.resize_ul($lid_LIDSolver_S_N_LID_TYPES_38 < 0 ? $lid_LIDSolver_S_N_LID_TYPES_38 + 0x10000000000000000 : $lid_LIDSolver_S_N_LID_TYPES_38)
    @groups_.a[0].type = 0
    @groups_.a[1].type = 1
    @groups_.a[2].type = 2
    @groups_.a[3].type = 3
    @groups_.a[4].type = 4
    @groups_.a[5].type = 5
    @groups_.a[6].type = 6
    @groups_.a[7].type = 7
    ucfRainDepth = F_ucf_UCF(1, ctx.options)
    ucfRainfall = F_ucf_UCF(0, ctx.options)
    ucfLength = F_ucf_UCF(3, ctx.options)
    ucfLength2 = ucfLength * ucfLength
    n_usage = ctx.lid_usage.count()
    ctx.lid_usage.resize_wb(n_usage)
    if n_usage == 0
      __r1 = @groups_
      __i2_n = __r1.n
      __i2 = 0
      while __i2 < __i2_n
        g = __r1.a[__i2]
        g.resize(0)
        __i2 += 1
      end
      return
    end
    type_counts = [0, 0, 0, 0, 0, 0, 0, 0]
    j = 0
    j = 0
    while j < n_usage
