class Rdii_iface_RdiiInterfaceFile
  include Cpp::ICopy
  include Cpp::IDisposable
  attr_accessor :fp_, :writing_, :binary_, :rdii_step_, :flow_units_, :node_idx_, :flows_, :start_date_, :end_date_, :have_record_

  def initialize
    @fp_ = nil
    @writing_ = false
    @binary_ = false
    @rdii_step_ = 0
    @flow_units_ = 0
    @node_idx_ = nil
    @flows_ = nil
    @start_date_ = 0.0
    @end_date_ = 0.0
    @have_record_ = false
  end

  def openForRead(ctx, path)
    self.close()
    @writing_ = false
    @have_record_ = false
    @start_date_ = $F_rdii_iface__anon_hydrology_RdiiInterface_cpp_NO_DATE_RdiiInterface
    @end_date_ = $F_rdii_iface__anon_hydrology_RdiiInterface_cpp_NO_DATE_RdiiInterface
    @fp_ = F_io_fopen_utf8(path, R_Lit("rb"))
    if !(!@fp_.nil?)
      return -1
    end
    stamp = R_BufOf(16, [])
    stamp_len = R_strlen($F_rdii_iface_RDII_FILE_STAMP_RdiiInterface)
    if (Mem_fread_CPtr_ul_ul_CFile(stamp, 1, stamp_len, @fp_) == stamp_len) && (R_strncmp(stamp, $F_rdii_iface_RDII_FILE_STAMP_RdiiInterface, stamp_len) == 0)
      @binary_ = true
      rc = self.readBinaryHeader(ctx)
      if rc != 0
        self.close()
        return rc
      end
    else
      R_fclose(@fp_)
      @fp_ = F_io_fopen_utf8(path, R_Lit("rt"))
      if !(!@fp_.nil?)
        return -1
      end
      @binary_ = false
      rc_2 = self.readTextHeader(ctx)
      if rc_2 != 0
        self.close()
        return rc_2
      end
    end
    self.readNextRecord()
    return 0
  end

  def openForWrite(path, rdii_step, node_idx)
    self.close()
    if node_idx.n == 0
      return -2
    end
    @fp_ = F_io_fopen_utf8(path, R_Lit("wb"))
    if !(!@fp_.nil?)
      return -1
    end
    @writing_ = true
    @binary_ = true
    @rdii_step_ = (rdii_step > 0) ? rdii_step : 300
    @node_idx_.Assign_VecT(node_idx)
    @flows_.assign_ul_T(@node_idx_.n, 0.0)
    Mem_fwrite_CPtr_ul_ul_CFile($F_rdii_iface_RDII_FILE_STAMP_RdiiInterface, 1, R_strlen($F_rdii_iface_RDII_FILE_STAMP_RdiiInterface), @fp_)
    step = @rdii_step_
    n = (@node_idx_.n + 0x80000000 & 0xFFFFFFFF) - 0x80000000
    R_fwriteI1(step, @fp_)
    R_fwriteI1(n, @fp_)
    idx = Algo_VecFrom__I(@node_idx_.begin(), @node_idx_.end())
    Mem_fwrite_PtrT_ul_ul_CFile__I(idx.data(), 4, idx.n, @fp_)
    return 0
  end

  def applyFlows(ctx, current_date)
