class SWMM_SnowpackEdit
  include Cpp::ICopy
  attr_accessor :name, :surface, :removal, :removal_subcatch, :ueb

  def initialize
    @name = CPtr_ZERO
    @surface = nil
    @removal = nil
    @removal_subcatch = CPtr_ZERO
    @ueb = nil
  end

  def __init_d
    @name = CPtr_ZERO
    @surface = Arr_Make2__D(3, 7)
    @removal = Arr_Make__D(6)
    @removal_subcatch = CPtr_ZERO
    @ueb = SWMM_UebSnowpack__new()
  end

  def ctor_SWMM_SnowpackEdit
    self.__init_d()
  end

  def Clone
    o = SWMM_SnowpackEdit.new
    o.__CopyFrom_SWMM_SnowpackEdit(self)
    return o
  end

  def __CopyFrom_SWMM_SnowpackEdit(s)
    @name = s.name
    @surface = Arr_Clone(s.surface)
    @removal = Arr_Clone__D(s.removal)
    @removal_subcatch = s.removal_subcatch
    @ueb = s.ueb.nil? ? nil : s.ueb.Clone()
  end

  def Assign(s)
    if self.equal?(s)
      return
    end
    @name = s.name
    Arr_Assign(@surface, s.surface)
    Arr_Assign__D(@removal, s.removal)
    @removal_subcatch = s.removal_subcatch
    @ueb.Assign(s.ueb)
  end

  def MoveFrom(s)
    if self.equal?(s)
      return
    end
    @name = s.name
    @surface = s.surface
    @removal = s.removal
    @removal_subcatch = s.removal_subcatch
    @ueb = s.ueb
    s.ueb = SWMM_UebSnowpack__new()
  end
end

