  def write_timing(f, ctx)
    begin_str = R_LitN("", 64)
    end_str = R_LitN("", 64)
    wall_end = Cpp::Cell.new(0)
    __b1 = [wall_end.v]
    Mv_Back__LL(R_time_Ptrl(NewPtrL_TA_l(__b1, 0)), wall_end, __b1)
    wall_start = Cpp::Cell.new(((ctx.wall_start != 0) ? FR_SimulationContext_wall_start.new(ctx) : wall_end).v)
    __b2 = [wall_start.v]
    ct = Mv_Back__OL(R_ctime_Ptrl(NewPtrL_TA_l(__b2, 0)), wall_start, __b2)
    if !ct.get_IsNull()
      R_strncpy(begin_str, ct, 63)
      nl = R_strchr(begin_str, 10)
      if !nl.get_IsNull()
        nl.set(0, 0)
      end
    end
    __b3 = [wall_end.v]
    ct_2 = Mv_Back__OL(R_ctime_Ptrl(NewPtrL_TA_l(__b3, 0)), wall_end, __b3)
    if !ct_2.get_IsNull()
      R_strncpy(end_str, ct_2, 63)
      nl_2 = R_strchr(end_str, 10)
      if !nl_2.get_IsNull()
        nl_2.set(0, 0)
      end
    end
    R_fprintf(f, R_Lit("\n\n  Analysis begun on:  %s"), begin_str)
    R_fprintf(f, R_Lit("\n  Analysis ended on:  %s"), end_str)
    R_fprintf(f, R_Lit("\n  Total elapsed time: "))
    elapsed_secs = R_difftime(wall_end.v, wall_start.v)
    if elapsed_secs < 1.0
      R_fprintf(f, R_Lit("< 1 sec"))
    else
      es = Conv_D2L(elapsed_secs)
      days = idiv(es, 86400)
      rem = es.remainder(86400)
      if days > 0
        R_fprintf(f, R_Lit("%ld."), I64(days))
      end
      R_fprintf(f, R_Lit("%02ld:%02ld:%02ld"), I64(idiv(rem, 3600)), I64(idiv(rem.remainder(3600), 60)), I64(rem.remainder(60)))
    end
    R_fprintf(f, R_Lit("\n"))
  end

