      gi = (_u1 = @mesh_.cell_geom.a[c]) < 0 ? _u1 + 0x10000000000000000 : _u1
      if gi >= @mesh_.geom.n
        c += 1
        next
      end
      g = @mesh_.geom.a[gi]
      area_x = @state_.cell_a.a[c]
      if !(area_x > 0.0)
        c += 1
        next
      end
      vol_ft3 = area_x * @mesh_.cell_dx.a[c]
      if !(vol_ft3 > 0.0)
        c += 1
        next
      end
      h = F_fv_kernels_depthOfArea(g, area_x)
      if !(h > 0.0)
        c += 1
        next
      end
      rh = F_fv_kernels_hydRadOfDepth(g, h)
      if !(rh > 0.0)
        c += 1
        next
      end
      bed_m2 = ((rh != 0.0 ? area_x / rh : fdiv0(area_x, rh)) * @mesh_.cell_dx.a[c]) * kSqFtToSqM
      sd_c = F_transport_heat_sedimentFor(ctx, HeatElement_link(self.cellLink(c)))
      vol_w = vol_ft3 * kCuFtToCuM
      vol_b = bed_m2 * sd_c.bed_thickness
      q_exch = F_transport_heat_bedExchangeQ(sd_c, bed_m2)
      if (!(q_exch > 0.0)) || (!(vol_b > 0.0))
        c += 1
        next
      end
      sp = 0
      sp = 0
      while sp < une
        cw = Cpp::ArrRef.new(@state_.cell_phi.a, ((sp * unc) + c) & 0xFFFFFFFFFFFFFFFF)
        cb = Cpp::ArrRef.new(bed.cell_conc.a, ((sp * unc) + c) & 0xFFFFFFFFFFFFFFFF)
        st = F_transport_heat_exchangePair(cw.v, cb.v, vol_w, vol_b, q_exch, dt)
        cw.v += st.dc_w
        cb.v += st.dc_b
        sp += 1
      end
      c += 1
    end
  end

  def cellLink(cell)
    if cell >= @mesh_.cell_conduit.n
      return -1
    end
    cr = @mesh_.cell_conduit.a[cell]
    if (cr < 0) || ((cr < 0 ? cr + 0x10000000000000000 : cr) >= @mesh_.conduit_link.n)
      return -1
    end
    return @mesh_.conduit_link.a[cr < 0 ? cr + 0x10000000000000000 : cr]
  end

