def ucf_DisplayUnits_from(opts)
  d = ucf_DisplayUnits__new()
  fu = opts.flow_units
  if (fu < 0) || (fu > 5)
    fu = 0
  end
  us = F_ucf_getUnitSystem(fu)
  si = us == 1
  d.unit_system = us
  d.flow_units = fu
  d.flow = $F_ucf_Qcf_UnitConversion[fu]
  d.length = $F_ucf_Ucf_UnitConversion[3][us]
  d.volume = $F_ucf_Ucf_UnitConversion[5][us]
  d.rainfall = $F_ucf_Ucf_UnitConversion[0][us]
  d.raindepth = $F_ucf_Ucf_UnitConversion[1][us]
  d.evaprate = $F_ucf_Ucf_UnitConversion[2][us]
  d.landarea = $F_ucf_Ucf_UnitConversion[4][us]
  d.mvol = si ? (2.83168E-05) : $F_ucf_FT3_TO_MGAL_UnitConversion
  d.landvol = si ? (2.83168E-06) : ($F_ucf_ACRES_TO_FT2_UnitConversion != 0.0 ? 1.0 / $F_ucf_ACRES_TO_FT2_UnitConversion : fdiv0(1.0, $F_ucf_ACRES_TO_FT2_UnitConversion))
  d.flow_word = $F_ucf_FlowUnitWords[fu]
  d.length_word = si ? R_Lit("Meters") : R_Lit("Feet")
