def LinkData_lstep_bin(dt, rs)
  b = 0
  edge = 0.5 * rs
  while (b < ((($LinkData_N_LSTEP_BINS - 1) + 0x80000000 & 0xFFFFFFFF) - 0x80000000)) && (dt <= edge)
    b += 1
    edge *= 0.5
  end
  return b
end

