def hydraulics_TimestepController_compute_next(ctx, dt_cfl)
  opt = ctx.options
  min_step = opt.min_routing_step
  dt = dt_cfl < opt.routing_step ? dt_cfl : opt.routing_step
  total_msec = opt.totalDurationMs()
  if (ctx.elapsed_ms + (1000.0 * dt)) > total_msec
    dt = (total_msec - ctx.elapsed_ms) / 1000.0
    dt = dt < 0.001 ? 0.001 : dt
  end
  if (ctx.dt_controls_remaining > 0.0) && (ctx.dt_controls_remaining < dt)
    dt = ctx.dt_controls_remaining
  end
  if dt <= 0.0
    dt = min_step
  end
  return dt
end

def hydraulics_TimestepController_advance(ctx, dt_taken)
  ctx.current_time += dt_taken
  ctx.current_date = F_datetime_addSeconds(ctx.options.start_date, ctx.current_time)
  ctx.old_elapsed_ms = ctx.elapsed_ms
  ctx.elapsed_ms = ctx.elapsed_ms + (1000.0 * dt_taken)
  if ctx.dt_controls_remaining > 0.0
    ctx.dt_controls_remaining -= dt_taken
    if ctx.dt_controls_remaining < 0.0
      ctx.dt_controls_remaining = 0.0
    end
  end
end

def hydraulics_TimestepController_reset_output_timer(ctx)
  ctx.next_report_ms = ctx.next_report_ms + (1000.0 * ctx.options.report_step)
end

def hydraulics_TimestepController_output_due(ctx)
  return ctx.elapsed_ms >= ctx.next_report_ms
end

def hydraulics_TimestepController_simulation_complete(ctx)
  return ctx.elapsed_ms >= ctx.options.totalDurationMs()
end

