def fv_PressurizedHeadSolver_cellPressurized(mesh, state, cell)
  uc = cell < 0 ? cell + 0x10000000000000000 : cell
  if !(state.cell_tpa.n == 0)
    return state.cell_tpa.a[uc] != 0
  end
  g = mesh.geom.a[(_u1 = mesh.cell_geom.a[uc]) < 0 ? _u1 + 0x10000000000000000 : _u1]
  return (!(g.is_open != 0)) && (state.cell_h.a[uc] >= g.y_crown)
end

def fv_PressurizedHeadSolver_faceModeOf(mesh, state, f)
  uf = f < 0 ? f + 0x10000000000000000 : f
  if mesh.face_gate.a[uf] != 0
    return 0
  end
  if mesh.face_culvert.a[uf] >= 0
    return 0
  end
  cl = mesh.face_cl.a[uf]
  cr = mesh.face_cr.a[uf]
  nd = mesh.face_node.a[uf]
  if (nd < 0) && ((cl < 0) || (cr < 0))
    return 0
  end
  pl = false
  pr = false
  cell_side_press = false
  if cl >= 0
    pl = fv_PressurizedHeadSolver_cellPressurized(mesh, state, cl)
    cell_side_press = cell_side_press || pl
  end
  if cr >= 0
    pr = fv_PressurizedHeadSolver_cellPressurized(mesh, state, cr)
    cell_side_press = cell_side_press || pr
  end
  if nd >= 0
    gp = fv_PressurizedHeadSolver_ghostPressurized(mesh, state, f)
    if cl < 0
      pl = gp
    end
    if cr < 0
      pr = gp
    end
  end
  if !cell_side_press
    return 0
  end
  return ((pl && pr) ? 1 : 2) & 0xFF
end

def fv_PressurizedHeadSolver_ghostPressurized(mesh, state, f)
  uf = f < 0 ? f + 0x10000000000000000 : f
  nd = mesh.face_node.a[uf]
  if nd < 0
    return false
  end
  other = ((mesh.face_cl.a[uf] >= 0) ? Cpp::ArrRef.new(mesh.face_cl.a, uf) : Cpp::ArrRef.new(mesh.face_cr.a, uf)).v
  if other < 0
    return false
  end
  g = mesh.geom.a[(_u1 = mesh.cell_geom.a[other < 0 ? other + 0x10000000000000000 : other]) < 0 ? _u1 + 0x10000000000000000 : _u1]
  if g.is_open != 0
    return false
  end
  if ((!(state.cell_tpa.n == 0)) && (state.cell_tpa.a[other < 0 ? other + 0x10000000000000000 : other] != 0)) && (mesh.node_sur_depth.a[nd < 0 ? nd + 0x10000000000000000 : nd] > 0.0)
    return true
  end
  hg = state.node_head.a[nd < 0 ? nd + 0x10000000000000000 : nd] - mesh.face_zb.a[uf]
  return hg >= g.y_crown
end

