def rdii_RDIISolver_getRainInterval(uh, wet_step)
  ri = Conv_D2I(wet_step)
  if ri <= 0
    ri = 300
  end
  m = 0
  m = 0
  while m < 12
    k = 0
    k = 0
    while k < 3
      tp = uh.tPeak[m][k]
      if tp > 0.0
        tLimb = Conv_D2I(tp)
        if tLimb > 0
          ri = tLimb < ri ? tLimb : ri
        end
        tFall = Conv_D2I(uh.tBase[m][k] - tp)
        if tFall > 0
          ri = tFall < ri ? tFall : ri
        end
      end
      k += 1
    end
    m += 1
  end
  return ri < 1 ? 1 : ri
end

def rdii_RDIISolver_getMaxPeriods(uh, response, rainInterval)
  if rainInterval <= 0
    return 0
  end
  k = response.remainder(3)
  nMax = 0
  m = 0
  m = 0
  while m < 12
    n = ((Conv_D2I((_n2 = uh.tBase[m][k]; (_d1 = rainInterval) != 0.0 ? _n2 / _d1 : fdiv0(_n2, _d1))) + 1) + 0x80000000 & 0xFFFFFFFF) - 0x80000000
    nMax = n < nMax ? nMax : n
    m += 1
  end
  return nMax
end

