def runoff_RunoffSolver_updatePondedDepth(depth, inflow, alpha, dStore, dt, t_runoff)
  tx = dt
  if (depth.v + (inflow * tx)) <= dStore
    depth.v += inflow * tx
  else
    dx = dStore - depth.v
    if (dx > 0.0) && (inflow > 0.0)
      tx -= inflow != 0.0 ? dx / inflow : fdiv0(dx, inflow)
      depth.v = dStore
    end
    if (alpha > 0.0) && (tx > 0.0)
      captured_inflow = inflow
      captured_alpha = alpha
      captured_dStore = dStore
      __b1 = [depth.v]
      __cap2 = captured_inflow
      __cap3 = captured_alpha
      __cap4 = captured_dStore
      _arg2 = NewPtrD_TA_l(__b1, 0)
      _arg3 = tx
      _arg4 = $F_runoff_ODETOL
      _arg5 = tx
      _lam1 = ->(p, d, dddt) do
        rx = d.get_Deref() - __cap4
        outflow = (rx > 0.0) ? (__cap3 * Math_Pow_d(rx, $F_runoff_MEXP)) : 0.0
        dddt.set_Deref(__cap2 - outflow)
        return
        nil
      end
      Mv_Back__ID(F_ode_integrate(_arg2, 1, 0.0, _arg3, _arg4, _arg5, _lam1), depth, __b1)
    else
      tx = tx < 0.0 ? 0.0 : tx
      depth.v += inflow * tx
    end
  end
  depth.v = depth.v < 0.0 ? 0.0 : depth.v
  t_runoff.v = tx
end

