def input_InputReader_parse_section_header(line)
  if (line.n < 3) || (((line.front() + 0x80 & 0xFF) - 0x80) != 91)
    return NewStr()
  end
  close = line.find_i_ul(93, 0)
  if close == 18446744073709551615
    return NewStr()
  end
  name = input_Tokenizer_trim(line.substr(1, (close - 1) & 0xFFFFFFFFFFFFFFFF))
  if name.n == 0
    return NewStr()
  end
  return input_Tokenizer_to_upper(name.Clone())
end

