def input_Tokenizer_strip_comment(line)
  in_quote = false
  i = 0
  while i < line.n
    c = (line.b[i] + 0x80 & 0xFF) - 0x80
    if c == 34
      in_quote = !in_quote
    elsif (c == 59) && (!in_quote)
      return line.substr(0, i)
    end
    i += 1
  end
  return line.Clone()
end

def input_Tokenizer_tokenize(line)
  stripped = input_Tokenizer_strip_comment(line.Clone())
  pure_csv = input_Tokenizer_is_pure_csv_line(stripped.Clone())
  tokens = Cpp::Cell.new(NewVec(K_MK4))
  tokens.v.reserve(8)
  i = 0
  n = stripped.n
  while i < n
    while (i < n) && ((((stripped.b[i] + 0x80 & 0xFF) - 0x80) == 32) || (((stripped.b[i] + 0x80 & 0xFF) - 0x80) == 9))
      i = (i + 1) & 0xFFFFFFFFFFFFFFFF
    end
    if i >= n
      break
    end
    if (((stripped.b[i] + 0x80 & 0xFF) - 0x80) == 44) && input_Tokenizer_comma_separates(stripped.Clone(), i, pure_csv)
      if (i == 0) || (((stripped.b[(i - 1) & 0xFFFFFFFFFFFFFFFF] + 0x80 & 0xFF) - 0x80) == 44)
        tokens.v.emplace_back(NewStr())
      end
      i = (i + 1) & 0xFFFFFFFFFFFFFFFF
      next
    end
    if ((stripped.b[i] + 0x80 & 0xFF) - 0x80) == 34
      i = (i + 1) & 0xFFFFFFFFFFFFFFFF
