def F_threadinfo_logicalCpus
  n = Sys_hardware_concurrency()
  return (n + 0x80000000 & 0xFFFFFFFF) - 0x80000000
end

def F_threadinfo_ompMaxThreads
  n = 1
  return (n > 0) ? n : 1
end

def F_threadinfo_perfCores
  return 0
end

def F_threadinfo_hostReservedThreads
  s = R_getenv(R_Lit("OPENSWMM_HOST_RESERVED_THREADS"))
  if (!(!s.get_IsNull())) || (!(s.get(0) != 0))
    return 0
  end
  n = R_atoi(s)
  return (n > 0) ? n : 0
end

def F_threadinfo_resolveRequested(requested, what, warnings)
  omp_max = F_threadinfo_ompMaxThreads()
  if requested <= 0
    return omp_max
  end
  nt = requested
  if !(!warnings.nil?)
    return nt
  end
  buf = R_Buf_i(512)
  logical = F_threadinfo_logicalCpus()
  reserved = F_threadinfo_hostReservedThreads()
  if (logical > 0) && ((((nt + reserved) + 0x80000000 & 0xFFFFFFFF) - 0x80000000) > logical)
    if reserved > 0
      R_snprintf_CPtr_ul_CPtr_oA(buf, 512, R_Lit("THREADS = %d plus the %d threads the host application reserves for itself exceed the %d logical processors on this machine (%s). The run is oversubscribed and is likely to be slower; active spin-wait is disabled for this run."), nt, reserved, logical, what)
    else
      R_snprintf_CPtr_ul_CPtr_oA(buf, 512, R_Lit("THREADS = %d exceeds the %d logical processors on this machine (%s). The run will be oversubscribed and is likely to be slower; active spin-wait is disabled for this run."), nt, logical, what)
    end
    warnings.emplace_back(Str_from_CPtr(buf.Clone()))
  elsif nt > omp_max
    R_snprintf_CPtr_ul_CPtr_oA(buf, 512, R_Lit("THREADS = %d exceeds the OpenMP limit of %d in this process (OMP_NUM_THREADS / OMP_THREAD_LIMIT / CPU affinity) for the %s; requesting %d anyway."), nt, omp_max, what, nt)
    warnings.emplace_back(Str_from_CPtr(buf.Clone()))
  end
  return nt
end

def F_threadinfo_dwThreads(requested, n_conduits, warnings)
  nt = F_threadinfo_resolveRequested(requested, R_Lit("dynamic wave"), warnings)
  if nt > 1
    cap = idiv(n_conduits, $F_threadinfo_kMinConduitsPerThread)
    if cap < 1
      cap = 1
    end
    if cap < nt
      if (requested > 0) && (!warnings.nil?)
        buf = R_Buf_i(256)
        R_snprintf_CPtr_ul_CPtr_oA(buf, 256, R_Lit("THREADS = %d reduced to %d for dynamic wave: the model has only %d conduits (%d per thread minimum)."), requested, cap, n_conduits, $F_threadinfo_kMinConduitsPerThread)
        warnings.emplace_back(Str_from_CPtr(buf.Clone()))
      end
      nt = cap
    end
  end
  if (requested == 0) && (nt > 1)
    pcores = F_threadinfo_perfCores()
    if (pcores > 2) && (nt > (((pcores - 2) + 0x80000000 & 0xFFFFFFFF) - 0x80000000))
      nt = ((pcores - 2) + 0x80000000 & 0xFFFFFFFF) - 0x80000000
    end
  end
  return nt
end

def F_ucf_UCF(quantity, opts)
  fu = opts.flow_units
  if quantity < 10
    us = F_ucf_getUnitSystem(fu)
    if (quantity >= 0) && (quantity <= 9)
      return $F_ucf_Ucf_UnitConversion[quantity][us]
    end
    return 1.0
  end
  if (fu >= 0) && (fu <= 5)
    return $F_ucf_Qcf_UnitConversion[fu]
  end
  return 1.0
end

def F_ucf_getUnitSystem(flow_units)
  return (flow_units >= 3) ? 1 : 0
end

