def F_fv_advanceNetworkChecked(solver, start, target, forcing)
  if ((!start.finite?) || (!target.finite?)) || (target < start)
    raise NewInvalidArgument_Str(Str_from_CPtr(R_Lit("FV routing times must be finite and ordered.")))
  end
  reached = solver.advance(start, target, forcing)
  tolerance = 3.552713678800501E-15 * M_max_dA([1.0, start.abs, target.abs])
  if ((!reached.finite?) || (reached < start)) || ((reached - target).abs > tolerance)
    raise NewRuntimeError_Str(Str_from_CPtr(R_Lit("FV backend did not reach the requested routing time; partial results were not published.")))
  end
  return reached
end

