def F_transport_domainName(d)
  case d
  when 0
    return R_Lit("Runoff / LID")
  when 1
    return R_Lit("Groundwater")
  when 2
    return R_Lit("1D network")
  when 3
    return R_Lit("2D surface")
  else
    return R_Lit("?")
  end
end

def F_transport_speciesClassName(c)
  case c
  when 0
    return R_Lit("Pollutants")
  when 1
    return R_Lit("MSX")
  when 2
    return R_Lit("Age")
  when 3
    return R_Lit("Temperature")
  else
    return R_Lit("?")
  end
end

def F_transport_formatReportBlock(m)
  out = Cpp::Cell.new(NewStr())
  out.v.append_CPtr(R_Lit("  Transport by domain (Domain x Species; on(n) = rows carried,\n"))
  out.v.append_CPtr(R_Lit("  off:KEY = switched off by that option, n/a = not carried):\n"))
  buf = R_Buf_i(256)
  R_snprintf_CPtr_ul_CPtr_oA(buf, 256, R_Lit("  %-14s %-14s %-14s %-14s %-14s\n"), R_Lit(""), R_Lit("Pollutants"), R_Lit("MSX"), R_Lit("Age"), R_Lit("Temperature"))
  out.v.append_CPtr(buf)
  d = 0
  d = 0
  while d < 4
    line = NewStr_CPtr(R_Lit("  "))
    R_snprintf_CPtr_ul_CPtr_oA(buf, 256, R_Lit("%-14s "), F_transport_domainName(d))
    line.append_CPtr(buf)
    c = 0
    c = 0
    while c < 4
      cell = m.cells[d][c]
      tok = NewStr()
      case cell.state
      when 0
        tok.MoveFrom(Str_Cat_Str_CPtr(Str_Cat_CPtr_Str(R_Lit("on("), Str_to_string_i(cell.count)), R_Lit(")")))
      when 1
        tok.MoveFrom(Str_Cat_CPtr_Str(R_Lit("off:"), cell.reason))
      else
        tok.Assign_CPtr(R_Lit("n/a"))
      end
      R_snprintf_CPtr_ul_CPtr_oA(buf, 256, R_Lit("%-14s "), tok.c_str())
      line.append_CPtr(buf)
      c += 1
    end
    out.v.append_Str(line)
    out.v.append_i(10)
    d += 1
  end
  any = false
  d_2 = 0
  d_2 = 0
  while d_2 < 4
    c_2 = 0
    c_2 = 0
    while c_2 < 4
      cell_2 = m.cells[d_2][c_2]
      if (cell_2.state != 2) || (cell_2.reason.n == 0)
        c_2 += 1
        next
      end
      if !any
        out.v.append_CPtr(R_Lit("  n/a because:\n"))
        any = true
      end
      R_snprintf_CPtr_ul_CPtr_oA(buf, 256, R_Lit("    %-14s %-12s %s\n"), F_transport_domainName(d_2), F_transport_speciesClassName(c_2), cell_2.reason.c_str())
      out.v.append_CPtr(buf)
      c_2 += 1
    end
    d_2 += 1
  end
  return Mv_Take(out, K_MK4)
end

def F_transport_registerArdComponent
