def F_transport_warnIfFvDispersionKeyIgnored(ctx)
  if ctx.options.fv.dispersion == 0.0
    return
  end
  if ctx.options.quality_solver != 1
    return
  end
  ctx.warnings.push_back(NewStr_CPtr(R_Lit("[OPTIONS] FV_DISPERSION is set but does not configure the Eulerian ARD engine \xE2\x80\x94 it reads dispersion from the transport.ard component (model.ard: [TRANSPORT_OPTIONS] DISPERSION OFF|FISCHER|<value> and [CONDUIT_DISPERSION] rows). No dispersion is applied from this key. Unifying the FV_*/ARD_* option surface arrives with plan phase E5.")))
end

def F_transport_resolveArdTransportRows(ctx, errors)
  cfg = ctx.ard_config
  cfg.bc_node.clear()
  cfg.bc_msx.clear()
  cfg.bc_value.clear()
  cfg.bc_ts.clear()
  cfg.src_link.clear()
  cfg.src_msx.clear()
  cfg.src_value.clear()
  cfg.src_ts.clear()
  cfg.transport_rows_resolved = false
  if (!cfg.configured) || (!cfg.any_transport_rows())
    cfg.transport_rows_resolved = true
    return
  end
  _lam1 = ->(row, sec) do
    s = ctx.reactions.find_species(row.species.Clone())
    if s >= 0
      return s
    end
    if ctx.species_registry.find(row.species.Clone()) >= 0
      errors.push_back(Str_Cat_Str_CPtr(Str_Cat_Str_Str(Str_Cat_Str_CPtr(Str_Cat_Str_Str(Str_Cat_Str_CPtr(Str_Cat_Str_CPtr(NewStr_CPtr(R_Lit("[")), sec), R_Lit("] '")), row.element), R_Lit("': '")), row.species), R_Lit("' is a pollutant \xE2\x80\x94 pollutant loading uses the legacy pathways ([INFLOWS], DWF, washoff); transport boundaries/sources apply to MSX species only (E5a).")))
    else
      errors.push_back(Str_Cat_Str_CPtr(Str_Cat_Str_Str(Str_Cat_Str_CPtr(Str_Cat_Str_Str(Str_Cat_Str_CPtr(Str_Cat_Str_CPtr(NewStr_CPtr(R_Lit("[")), sec), R_Lit("] '")), row.element), R_Lit("': unknown species '")), row.species), R_Lit("' \xE2\x80\x94 declare it in the reactions component's [REACTION_SPECIES].")))
    end
    return -1
  end
  resolve_species = _lam1
  _lam2 = ->(row_2, sec_2) do
    t = ctx.tables.find_by_kind(row_2.ts_name.Clone(), true)
    if t < 0
      errors.push_back(Str_Cat_Str_CPtr(Str_Cat_Str_Str(Str_Cat_Str_CPtr(Str_Cat_Str_Str(Str_Cat_Str_CPtr(Str_Cat_Str_CPtr(NewStr_CPtr(R_Lit("[")), sec_2), R_Lit("] '")), row_2.element), R_Lit("': unknown timeseries '")), row_2.ts_name), R_Lit("'.")))
    end
    return t
  end
  resolve_ts = _lam2
  __r1 = cfg.boundary_rows
  __i2_n = __r1.n
  __i2 = 0
  while __i2 < __i2_n
    row_3 = __r1.a[__i2]
    nd = ctx.node_names.find(row_3.element.Clone())
    if nd < 0
      errors.push_back(Str_Cat_Str_CPtr(Str_Cat_CPtr_Str(R_Lit("[TRANSPORT_BOUNDARIES] unknown node '"), row_3.element), R_Lit("'.")))
      __i2 += 1
      next
    end
    s_2 = resolve_species.call(row_3, R_Lit("TRANSPORT_BOUNDARIES"))
    if s_2 < 0
      __i2 += 1
      next
    end
    ts = -1
    if row_3.is_ts && ((ts = resolve_ts.call(row_3, R_Lit("TRANSPORT_BOUNDARIES"))) < 0)
      __i2 += 1
      next
    end
    dup = false
    i = 0
    while i < cfg.bc_node.n
      if (cfg.bc_node.a[i] == nd) && (cfg.bc_msx.a[i] == s_2)
        errors.push_back(Str_Cat_Str_CPtr(Str_Cat_Str_Str(Str_Cat_Str_CPtr(Str_Cat_CPtr_Str(R_Lit("[TRANSPORT_BOUNDARIES] duplicate row for node '"), row_3.element), R_Lit("' species '")), row_3.species), R_Lit("'.")))
        dup = true
        break
      end
      i += 1
    end
    if dup
      __i2 += 1
      next
    end
    cfg.bc_node.push_back(nd)
    cfg.bc_msx.push_back(s_2)
    cfg.bc_value.push_back(row_3.value)
    cfg.bc_ts.push_back(row_3.is_ts ? ts : (-1))
    __i2 += 1
  end
  __r3 = cfg.source_rows
  __i4_n = __r3.n
  __i4 = 0
  while __i4 < __i4_n
    row_4 = __r3.a[__i4]
    link = ctx.link_names.find(row_4.element.Clone())
    if (link < 0) || (ctx.link_subtypes.conduit_row(link) < 0)
      errors.push_back(Str_Cat_Str_CPtr(Str_Cat_CPtr_Str(R_Lit("[TRANSPORT_SOURCES] '"), row_4.element), R_Lit("' is not a conduit \xE2\x80\x94 distributed sources apply to conduits.")))
      __i4 += 1
      next
    end
    s_3 = resolve_species.call(row_4, R_Lit("TRANSPORT_SOURCES"))
    if s_3 < 0
      __i4 += 1
      next
    end
    ts_2 = -1
    if row_4.is_ts && ((ts_2 = resolve_ts.call(row_4, R_Lit("TRANSPORT_SOURCES"))) < 0)
      __i4 += 1
      next
    end
    dup_2 = false
    i_2 = 0
    while i_2 < cfg.src_link.n
      if (cfg.src_link.a[i_2] == link) && (cfg.src_msx.a[i_2] == s_3)
        errors.push_back(Str_Cat_Str_CPtr(Str_Cat_Str_Str(Str_Cat_Str_CPtr(Str_Cat_CPtr_Str(R_Lit("[TRANSPORT_SOURCES] duplicate row for conduit '"), row_4.element), R_Lit("' species '")), row_4.species), R_Lit("'.")))
        dup_2 = true
        break
      end
      i_2 += 1
    end
    if dup_2
      __i4 += 1
      next
    end
    if (!row_4.is_ts) && (row_4.value < 0.0)
      ctx.warnings.push_back(Str_Cat_Str_CPtr(Str_Cat_Str_Str(Str_Cat_Str_CPtr(Str_Cat_CPtr_Str(R_Lit("[TRANSPORT_SOURCES] '"), row_4.element), R_Lit("' species '")), row_4.species), R_Lit("': negative rate is treated as EXTRACTION (D-NS1). Removal is clamped to the mass the conduit's cells actually hold.")))
    end
    cfg.src_link.push_back(link)
    cfg.src_msx.push_back(s_3)
    cfg.src_value.push_back($F_kLitersPerFt3 != 0.0 ? row_4.value / $F_kLitersPerFt3 : fdiv0(row_4.value, $F_kLitersPerFt3))
    cfg.src_ts.push_back(row_4.is_ts ? ts_2 : (-1))
    __i4 += 1
  end
  cfg.transport_rows_resolved = true
end

