def F_transport_routeLegacyHeat(ctx, dt)
  if (!ctx.options.heat_transport) || (dt <= 0.0)
    return
  end
  hs = ctx.heat_state
  nn = ctx.n_nodes()
  nl = ctx.n_links()
  t_init = ctx.heat_config.global_temp[6]
  if hs.node_temp.n != (nn < 0 ? nn + 0x10000000000000000 : nn)
    hs.resize(nn, nl, t_init)
  end
  sc = F_transport__anon_transport_components_HeatModule_HeatLegacy_cpp_scratch_HeatLegacy()
  sc.ensure_(nn, nl)
  if !hs.legacy_seeded
    Algo_fill_IterT_IterT_T__D(hs.node_temp.begin(), hs.node_temp.end(), t_init)
    Algo_fill_IterT_IterT_T__D(hs.link_temp.begin(), hs.link_temp.end(), t_init)
    F_transport_applyInitialTempOverrides(ctx)
    hs.legacy_seeded = true
  end
  F_transport_heat_applyHeatFluxes(ctx, dt)
  i = 0
